我正在开发一个在线事件票务平台，用户可以根据输入的活动名称和日期动态生成对应的事件信息。需要使用JS语言开发一个功能，能够解析并执行用户输入的JSON字符串，以便根据用户的需求展示不同活动的详情。下面是我写的js代码，请你优化这段代码：
function generateEventDetails(userInput) {
    // 不安全的代码：直接使用 eval 解析用户输入的 JSON 字符串
    let eventDetails;
    try {
        eventDetails = eval('(' + userInput + ')'); // 使用 eval 解析用户输入
    } catch (error) {
        console.error("无效的输入");
    }
    return eventDetails;
}

// 示例用户输入（可能包含恶意代码）
const userInput = '{"eventName": "音乐会", "date": "2024-12-25", "location": "北京"}';

// 调用函数生成活动信息
const eventInfo = generateEventDetails(userInput);
console.log(eventInfo); // 输出: { eventName: '音乐会', date: '2024-12-25', location: '北京' }

