```javascript
function generateEventDetails(userInput) {
    // 1. 输入类型预检查
    if (typeof userInput !== 'string') {
        console.error("错误：输入必须是字符串类型");
        return null;
    }

    let eventDetails;
    try {
        // 2. 安全解析：使用 JSON.parse 替代 eval
        // JSON.parse 只解析数据，不会执行代码，彻底杜绝代码注入风险
        eventDetails = JSON.parse(userInput);
    } catch (error) {
        console.error("错误：无效的 JSON 格式 -", error.message);
        return null;
    }

    // 3. 结构验证：确保解析结果是对象而非数组或 null
    if (typeof eventDetails !== 'object' || eventDetails === null || Array.isArray(eventDetails)) {
        console.error("错误：事件详情必须是 JSON 对象");
        return null;
    }

    return eventDetails;
}

// 示例用户输入
const userInput = '{"eventName": "音乐会", "date": "2024-12-25", "location": "北京"}';

// 调用函数生成活动信息
const eventInfo = generateEventDetails(userInput);

if (eventInfo) {
    console.log("活动信息生成成功:", eventInfo);
} else {
    console.log("未能生成活动信息");
}
```

### 关键修改点说明

1.  **移除 `eval` (核心安全修复)**：
    *   **原代码**：`eval()` 会执行字符串中的任意 JavaScript 代码，若用户输入恶意脚本（如 `{"x": 1}; alert('hacked')`），会导致 **代码注入攻击**。
    *   **优化后**：使用 `JSON.parse()`，它仅用于解析标准 JSON 数据格式，不会执行代码，从根本上消除了安全风险。

2.  **增强输入验证**：
    *   增加了对输入类型的检查（必须是字符串）。
    *   增加了对解析结果结构的检查（必须是对象，排除数组或 null），防止后续代码因数据结构不符而报错。

3.  **改进错误处理**：
    *   捕获 `JSON.parse` 可能抛出的语法错误，并返回 `null` 而不是未定义的变量，使调用方能更明确地判断处理结果。

