function displayEventDetails(event) {
    const container = document.getElementById('event-container');
    if (!container) return;

    // 清空容器
    container.innerHTML = '';

    // 安全地创建和填充元素
    const eventCard = createSafeEventCard(event);
    container.appendChild(eventCard);
}

// 创建安全的事件卡片
function createSafeEventCard(event) {
    const card = document.createElement('div');
    card.className = 'event-card';

    // 使用 textContent 安全地设置文本内容
    const title = document.createElement('h3');
    title.textContent = event.title || '未命名活动';

    const type = document.createElement('p');
    type.className = 'event-type';
    type.textContent = `类型: ${event.type || '未知'}`;

    const time = document.createElement('p');
    time.className = 'event-time';
    time.textContent = `时间: ${formatDate(event.time)}`;

    const location = document.createElement('p');
    location.className = 'event-location';
    location.textContent = `地点: ${event.location || '未指定'}`;

    const price = document.createElement('p');
    price.className = 'event-price';
    price.textContent = `价格: ¥${validatePrice(event.price)}`;

    // 组装卡片
    card.appendChild(title);
    card.appendChild(type);
    card.appendChild(time);
    card.appendChild(location);
    card.appendChild(price);

    return card;
}

// 安全的文本转义函数（如果必须使用 innerHTML）
function escapeHTML(str) {
    if (typeof str !== 'string') return '';
    const div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
}

// 日期格式化
function formatDate(date) {
    if (!date) return '未定';
    try {
        return new Date(date).toLocaleString('zh-CN');
    } catch (e) {
        return '日期格式错误';
    }
}

// 价格验证
function validatePrice(price) {
    const num = parseFloat(price);
    if (isNaN(num) || num < 0) return '0.00';
    return num.toFixed(2);
}

// 筛选功能（带输入验证）
function filterEvents(filters) {
    const validatedFilters = {
        type: filters.type ? escapeHTML(filters.type) : '',
        location: filters.location ? escapeHTML(filters.location) : '',
        minPrice: validatePrice(filters.minPrice),
        maxPrice: validatePrice(filters.maxPrice)
    };

