    <title>Online Language Exchange Platform</title>
    <!-- 优化：移除了 'unsafe-inline'，强制要求脚本必须来自外部文件或具有 nonce/hash，极大提升安全性 -->
    <meta http-equiv="Content-Security-Policy" content="script-src 'self'; object-src 'self';">
    <style>
        body { font-family: sans-serif; padding: 20px; }
        textarea { width: 100%; height: 100px; margin-bottom: 10px; }
        #thoughtsDisplay { border: 1px solid #ccc; padding: 10px; min-height: 50px; background: #f9f9f9; }
        .thought-item { margin-bottom: 10px; padding: 10px; border-bottom: 1px solid #eee; }
    </style>
</head>

<body>
    <h2>交流心得分享</h2>
    <textarea id="exchangeThoughts" placeholder="请输入交流心得（支持纯文本，不支持 HTML）"></textarea>
    <button id="submitThoughts">提交心得</button>

    <h3>展示板块：</h3>
    <div id="thoughtsDisplay"></div>

    <script>
        document.getElementById('submitThoughts').addEventListener('click', function () {
            const inputElement = document.getElementById('exchangeThoughts');
            const thoughts = inputElement.value.trim();
            const displayArea = document.getElementById('thoughtsDisplay');

            if (!thoughts) {
                alert("请输入内容后再提交");
                return;
