## 1. 前端 XSS 检测脚本

```javascript
// xss-tester.js
class XSSTester {
    constructor(targetUrl) {
        this.targetUrl = targetUrl;
        this.testPayloads = [
            '<script>alert("XSS1")</script>',
            '<img src=x onerror=alert("XSS2")>',
            '<svg onload=alert("XSS3")>',
            '<body onload=alert("XSS4")>',
            'javascript:alert("XSS5")',
            '<iframe src="javascript:alert(\'XSS6\')">',
            '<div onmouseover=alert("XSS7")>hover</div>',
            '<input onfocus=alert("XSS8") autofocus>',
            '<marquee onstart=alert("XSS9")>',
            '<details open ontoggle=alert("XSS10")>'
        ];
        this.results = [];
    }

    async testXSS() {
        console.log('🔍 开始XSS漏洞检测...\n');
        for (const payload of this.testPayloads) {
            const result = await this.testPayload(payload);
            this.results.push(result);
        }
        this.generateReport();
        return this.results;
    }

    async testPayload(payload) {
        const startTime = Date.now();
        let vulnerable = false;
        let response = '';

        try {
            // 模拟提交测试（需根据实际接口调整）
            const testResponse = await this.submitPayload(payload);
            response = testResponse;

            // 检测响应中是否包含未转义的payload
            if (this.containsUnescapedPayload(response, payload)) {
                vulnerable = true;
            }

            // 可选：在沙箱iframe中渲染检测
            const iframeResult = await this.testInSandbox(payload);
            if (iframeResult) {
                vulnerable = true;
            }
        } catch (error) {
            console.error(`测试失败: ${error.message}`);
        }

        return {
            payload,
            vulnerable,
            responseLength: response?.length || 0,
            testTime: Date.now() - startTime,
            timestamp: new Date().toISOString()
        };
    }

    async submitPayload(payload) {
        // 替换为实际提交接口
        const response = await fetch(this.targetUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ html: payload }),
            mode: 'cors'
        });
        return await response.text();
    }

    containsUnescapedPayload(response, payload) {
        const dangerous = ['<script', 'onerror=', 'onload=', 'javascript:'];
        return dangerous.some(tag => 
            response.toLowerCase().includes(tag.toLowerCase())
        );
    }

    async testInSandbox(payload) {
        return new Promise((resolve) => {
            const iframe = document.createElement('iframe');
            iframe.sandbox = 'allow-scripts';
            iframe.style.display = 'none';

            const timeout = setTimeout(() => {
                document.body.removeChild(iframe);
                resolve(false);
            }, 2000);

            window.addEventListener('message', function handler(event) {
                clearTimeout(timeout);
                window.removeEventListener('message', handler);
                document.body.removeChild(iframe);
                resolve(true);
            });

            const testHTML = `
                <html><body>
                ${payload}
                <script>
                    try {
                        if (typeof alert !== 'undefined') {
                            window.parent.postMessage('XSS_DETECTED', '*');
                        }
                    } catch(e) {}
                </script>
                </body></html>
            `;

            document.body.appendChild(iframe);
            iframe.contentWindow.document.write(testHTML);
        });
    }

    generateReport() {
        const vulnerable = this.results.filter(r => r.vulnerable);
        console.log('\n📊 XSS检测报告');
        console.log('='.repeat(50));
        console.log(`总测试用例: ${this.results.length}`);
        console.log(`存在漏洞: ${vulnerable.length}`);
        console.log(`安全通过率: ${((this.results.length - vulnerable.length) / this.results.length * 100).toFixed(2)}%`);

        if (vulnerable.length > 0) {
            console.log('\n⚠️  发现以下危险Payload:');
            vulnerable.forEach((r, i) => {
                console.log(`${i + 1}. ${r.payload.substring(0, 50)}...`);
            });
        } else {
            console.log('\n✅ 未检测到明显XSS漏洞');
        }
    }
}

