      console.log(`[成功] 已加载设备控制模块: ${scriptUrl}`);
      return module;
    } catch (err) {
      console.error(`[错误] 加载模块失败: ${scriptUrl}`, err);
      return null;
    }
  }

  // 注册设备
  registerDevice(deviceId, deviceInfo) {
    if (!deviceId || typeof deviceInfo !== 'object') {
      throw new Error('无效的设备信息');
    }

    const device = {
      id: deviceId,
      name: deviceInfo.name || '未知设备',
      type: deviceInfo.type || 'unknown',
      status: deviceInfo.status || 'offline',
      controlScript: deviceInfo.controlScript || null,
      lastUpdate: Date.now(),
      metadata: deviceInfo.metadata || {}
    };

    this.devices.set(deviceId, device);
    console.log(`[设备注册] ${device.name} (${deviceId})`);
    this.notifyListeners('deviceRegistered', device);
    return device;
  }

  // 更新设备状态
  updateDeviceStatus(deviceId, newStatus) {
    const device = this.devices.get(deviceId);
    if (!device) {
      console.warn(`[警告] 设备不存在: ${deviceId}`);
      return false;
    }

    const oldStatus = device.status;
    device.status = newStatus.status || device.status;
    device.lastUpdate = Date.now();

    if (newStatus.metadata) {
      device.metadata = { ...device.metadata, ...newStatus.metadata };
    }

    console.log(`[状态更新] ${device.name}: ${oldStatus} → ${device.status}`);
    this.notifyListeners('deviceStatusChanged', { deviceId, oldStatus, newStatus: device.status });
    return true;
  }

  // 控制设备（带权限和状态验证）
  async controlDevice(deviceId, command, params = {}) {
    const device = this.devices.get(deviceId);
    if (!device) {
      throw new Error(`设备不存在: ${deviceId}`);
    }

    if (device.status === 'offline') {
      throw new Error(`设备离线: ${device.name}`);
    }

    const allowedCommands = ['turnOn', 'turnOff', 'setBrightness', 'setTemperature', 'lock', 'unlock'];
    if (!allowedCommands.includes(command)) {
      throw new Error(`不允许的命令: ${command}`);
    }

    console.log(`[控制命令] ${device.name}: ${command}`, params);

    if (device.controlScript && this.isTrustedSource(device.controlScript)) {
      try {
        const module = await import(device.controlScript);
        if (module.executeCommand) {
          await module.executeCommand(command, params);
        }
      } catch (err) {
        console.error(`[命令执行失败] ${command}`, err);
        throw err;
      }
    }

    this.notifyListeners('deviceCommandExecuted', { deviceId, command, params });
    return true;
  }

  // 启动状态轮询更新
  startStatusPolling(intervalMs = 5000) {
    if (this.updateInterval) {
      clearInterval(this.updateInterval);
    }

    this.updateInterval = setInterval(async () => {
      for (const [deviceId, device] of this.devices.entries()) {
        try {
          const response = await fetch(`/api/device/${deviceId}/status`, {
            method: 'GET',
            headers: { 'Accept': 'application/json' },
            credentials: 'same-origin'
          });

          if (response.ok) {
            const data = await response.json();
            this.updateDeviceStatus(deviceId, data);
          }
        } catch (err) {
          console.warn(`[轮询失败] ${deviceId}`, err);
        }
      }
    }, intervalMs);

    console.log(`[状态轮询] 已启动，间隔: ${intervalMs}ms`);
  }

  // 停止状态轮询
  stopStatusPolling() {
    if (this.updateInterval) {
      clearInterval(this.updateInterval);
      this.updateInterval = null;
      console.log('[状态轮询] 已停止');
    }
  }

  // 事件监听机制
  on(event, callback) {
    if (!this.eventListeners.has(event)) {
      this.eventListeners.set(event, []);
    }
    this.eventListeners.get(event).push(callback);
  }

  off(event, callback) {
    const listeners = this.eventListeners.get(event);
    if (listeners) {
      const index = listeners.indexOf(callback);
      if (index > -1) listeners.splice(index, 1);
    }
  }

  notifyListeners(event, data) {
    const listeners = this.eventListeners.get(event) || [];
    listeners.forEach(cb => {
      try {
        cb(data);
      } catch (err) {
        console.error(`[事件回调错误] ${event}`, err);
      }
    });
  }

  // 获取所有设备
  getAllDevices() {
    return Array.from(this.devices.values());
  }

  // 获取设备
  getDevice(deviceId) {
    return this.devices.get(deviceId);
  }

  // 移除设备
  removeDevice(deviceId) {
    const device = this.devices.get(deviceId);
    if (device) {
      this.devices.delete(deviceId);
      console.log(`[设备移除] ${device.name} (${deviceId})`);
      this.notifyListeners('deviceRemoved', device);
      return true;
    }
    return false;
  }

  // 清理资源
  destroy() {
    this.stopStatusPolling();
    this.devices.clear();
    this.eventListeners.clear();
    console.log('[设备管理器] 已销毁');
  }
}

