    // 清理SVG内容，移除潜在危险元素和属性
    function sanitizeSVG(svgContent) {
      const parser = new DOMParser();
      const doc = parser.parseFromString(svgContent, 'image/svg+xml');
      const svg = doc.querySelector('svg');
      if (!svg) return '';

      // 移除危险标签
      const dangerousTags = ['script', 'style', 'foreignObject', 'iframe', 'object', 'embed'];
      dangerousTags.forEach(tag => {
        svg.querySelectorAll(tag).forEach(el => el.remove());
      });

      // 移除危险属性
      const dangerousAttrs = [
        'onload', 'onclick', 'onerror', 'onmouseover', 'onmouseout',
        'onfocus', 'onblur', 'onchange', 'onsubmit', 'onreset',
        'onselect', 'onkeydown', 'onkeyup', 'onkeypress', 'xlink:href'
      ];

      function cleanElement(el) {
        dangerousAttrs.forEach(attr => {
          if (el.hasAttribute(attr)) {
            el.removeAttribute(attr);
          }
        });

        // 清理 style 属性中的 expression 或 url()
        if (el.hasAttribute('style')) {
          const style = el.getAttribute('style');
          if (/expression\s*\(|url\s*\(/i.test(style)) {
            el.removeAttribute('style');
          }
        }

        // 递归清理子元素
        Array.from(el.children).forEach(cleanElement);
      }

      cleanElement(svg);

      // 添加安全属性
      svg.setAttribute('focusable', 'false');
      svg.removeAttribute('xmlns:xlink'); // 避免 xlink 相关攻击

      return new XMLSerializer().serializeToString(svg);
    }

