```javascript
const form = document.getElementById('postForm');
const feed = document.getElementById('feed');
const errorBox = document.getElementById('errorBox');
const STORAGE_KEY = 'social_posts';

let posts = JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];

function savePosts() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(posts));
}

function isValidUrl(str) {
  try {
    new URL(str);
    return true;
  } catch {
    return false;
  }
}

function showError(msg) {
  errorBox.textContent = msg;
  setTimeout(() => errorBox.textContent = '', 3000);
}

function renderPosts() {
  feed.innerHTML = '';
  posts.slice().reverse().forEach(post => {
    const div = document.createElement('div');
    div.className = 'post';

    let media = '';
    if (post.image) {
      media = `<div class="post-media"><img src="${post.image}" alt="图片" onerror="this.style.display='none'"/></div>`;
    } else if (post.video) {
      media = `<div class="post-media"><video controls><source src="${post.video}" type="video/mp4"/></video></div>`;
    }

    div.innerHTML = `
      <div class="post-content">${escapeHtml(post.text)}</div>
      ${media}
      <div class="post-meta">发布于：${new Date(post.timestamp).toLocaleString()}</div>
      <button class="delete-btn" data-id="${post.id}">删除</button>
    `;
    feed.appendChild(div);
  });

  document.querySelectorAll('.delete-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const id = btn.getAttribute('data-id');
      posts = posts.filter(p => p.id !== id);
      savePosts();
      renderPosts();
    });
  });
}

function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

form.addEventListener('submit', e => {
  e.preventDefault();
  errorBox.textContent = '';

  const text = document.getElementById('postText').value.trim();
  const imageUrl = document.getElementById('imageUrl').value.trim();
  const videoUrl = document.getElementById('videoUrl').value.trim();

  if (!text && !imageUrl && !videoUrl) {
    showError('请至少输入文字、图片或视频链接之一');
    return;
  }

  if (imageUrl && !isValidUrl(imageUrl)) {
    showError('图片链接格式不正确');
    return;
  }

  if (videoUrl && !isValidUrl(videoUrl)) {
    showError('视频链接格式不正确');
    return;
  }

  const newPost = {
    id: Date.now().toString(),
    text,
    image: imageUrl || null,
    video: videoUrl || null,
    timestamp: Date.now()
  };

  posts.push(newPost);
  savePosts();
  renderPosts();
  form.reset();
});

// 初始化渲染
renderPosts();
```

