# 课程信息防篡改安全方案

## 完整思路

```
┌─────────────┐    ┌──────────────┐    ┌─────────────┐
│   前端JS    │───▶│  后端API     │───▶│   数据库    │
│  验证签名   │    │  生成签名    │    │  课程数据   │
└─────────────┘    └──────────────┘    └─────────────┘
       │                   │
       ▼                   ▼
  客户端校验          服务器签名
```

## 1. 前端验证脚本 (client-verify.js)

```javascript
/**
 * 课程信息防篡改验证模块
 * 使用 HMAC-SHA256 验证数据完整性
 */

class CourseDataVerifier {
    constructor(publicKey) {
        this.publicKey = publicKey;
    }

    /**
     * 计算数据的 HMAC-SHA256 签名
     */
    async calculateSignature(data, secretKey) {
        const encoder = new TextEncoder();
        const keyData = encoder.encode(secretKey);
        const dataString = JSON.stringify(data);
        const dataBytes = encoder.encode(dataString);

        const key = await crypto.subtle.importKey(
            'raw',
            keyData,
            { name: 'HMAC', hash: 'SHA-256' },
            false,
            ['sign']
        );

        const signature = await crypto.subtle.sign('HMAC', key, dataBytes);
        return Array.from(new Uint8Array(signature))
            .map(b => b.toString(16).padStart(2, '0'))
            .join('');
    }

    /**
     * 验证课程数据是否被篡改
     */
    async verifyCourseData(courseData, receivedSignature) {
        try {
            // 移除签名和临时字段
            const { signature, timestamp, ...dataToVerify } = courseData;

            // 检查时间戳（防止重放攻击）
            if (timestamp) {
                const now = Date.now();
                const maxAge = 5 * 60 * 1000; // 5分钟有效期
                if (now - timestamp > maxAge) {
                    return {
                        valid: false,
                        reason: '数据已过期，请刷新页面'
                    };
                }
            }

            // 计算期望的签名
            const expectedSignature = await this.calculateSignature(
                dataToVerify,
                this.publicKey
            );

            // 比较签名
            if (expectedSignature !== receivedSignature) {
                return {
                    valid: false,
                    reason: '数据签名不匹配，可能已被篡改'
                };
            }

            return {
                valid: true,
                reason: '验证通过'
            };
        } catch (error) {
            return {
                valid: false,
                reason: `验证过程出错: ${error.message}`
            };
        }
    }

    /**
     * 获取并验证课程信息
     */
    async fetchAndVerifyCourse(courseId) {
        try {
            const response = await fetch(`/api/courses/${courseId}`, {
                method: 'GET',
                headers: {
                    'Content-Type': 'application/json',
                    'X-Request-Timestamp': Date.now().toString()
                }
            });

            if (!response.ok) {
                throw new Error(`HTTP ${response.status}`);
            }

            const data = await response.json();
            const verification = await this.verifyCourseData(
                data.course,
                data.signature
            );

            if (!verification.valid) {
                console.error('⚠️ 安全警告:', verification.reason);
                this.showSecurityWarning(verification.reason);
                return null;
            }

            console.log('✅ 数据验证通过');
            return data.course;
        } catch (error) {
            console.error('❌ 获取课程失败:', error);
            this.showSecurityWarning('网络请求失败');
            return null;
        }
    }

    /**
     * 显示安全警告
     */
    showSecurityWarning(message) {
        const warningDiv = document.createElement('div');
        warningDiv.className = 'security-warning';
        warningDiv.innerHTML = `
            <div class="warning-content">
                <h3>⚠️ 安全警告</h3>
                <p>${message}</p>
                <button onclick="location.reload()">刷新页面</button>
            </div>
        `;
        document.body.appendChild(warningDiv);
        document.body.style.pointerEvents = 'none';
    }
}

// 使用示例
