            ...course,
            timestamp: Date.now()
        };

        // 3. 生成签名
        const signature = signatureService.generateSignature(courseWithTimestamp);

        // 4. 返回数据和签名
        res.json({
            course: courseWithTimestamp,
            signature: signature
        });

    } catch (error) {
        res.status(500).json({ error: '服务器错误' });
    }
});

