  const refreshToken = req.cookies.refreshToken;
  if (!refreshToken) return res.status(401).json({ error: '无刷新 token' });

  jwt.verify(refreshToken, JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: '刷新 token 无效' });
    const { accessToken } = generateTokens(user.userId, user.email);
    setTokenCookies(res, accessToken, refreshToken);
    res.json({ message: 'Token 已刷新' });
  });
});

