# 优化后的用户登录和会话管理系统

```php
<?php
/**
 * 安全的用户登录和会话管理系统
 * 优化点：密码哈希、会话安全、输入验证、防止会话固定攻击
 */

// 配置会话安全参数（必须在 session_start() 之前）
ini_set('session.cookie_httponly', 1);
ini_set('session.cookie_secure', 1); // HTTPS 环境下启用
ini_set('session.use_strict_mode', 1);
ini_set('session.cookie_samesite', 'Strict');

// 启动会话
session_start();

/**
 * 用户认证类
 */
class AuthSystem {
    // 模拟用户数据库（实际应使用数据库）
    private $users = [
        'user' => '$2y$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2.uheWG/igi' // password 的哈希
    ];

    private $maxLoginAttempts = 5;
    private $lockoutTime = 300; // 5分钟

    /**
     * 用户登录
     */
    public function login($username, $password) {
        // 输入验证
        if (!$this->validateInput($username, $password)) {
            return ['success' => false, 'message' => '输入格式无效'];
        }

        // 检查是否被锁定
        if ($this->isLockedOut($username)) {
            return ['success' => false, 'message' => '账户暂时锁定，请稍后重试'];
        }

        // 验证用户
        if (isset($this->users[$username]) && 
            password_verify($password, $this->users[$username])) {

            // 重置登录尝试
            $this->resetLoginAttempts($username);

            // 防止会话固定攻击
            session_regenerate_id(true);

            // 设置会话数据
            $_SESSION['username'] = $username;
            $_SESSION['logged_in'] = true;
            $_SESSION['login_time'] = time();
            $_SESSION['ip_address'] = $this->getClientIP();
            $_SESSION['user_agent'] = $_SERVER['HTTP_USER_AGENT'];

            return ['success' => true, 'message' => '登录成功'];
        } else {
            // 记录失败尝试
            $this->recordFailedAttempt($username);
            return ['success' => false, 'message' => '用户名或密码错误'];
        }
    }

    /**
     * 用户登出
     */
    public function logout() {
        $_SESSION = [];

        if (ini_get("session.use_cookies")) {
            $params = session_get_cookie_params();
            setcookie(session_name(), '', time() - 42000,
                $params["path"], $params["domain"],
                $params["secure"], $params["httponly"]
            );
        }

        session_destroy();
        return ['success' => true, 'message' => '已安全登出'];
    }

    /**
     * 检查用户是否已登录
     */
    public function isLoggedIn() {
        if (!isset($_SESSION['logged_in']) || $_SESSION['logged_in'] !== true) {
            return false;
        }

        // 会话超时检查（30分钟）
        if (time() - $_SESSION['login_time'] > 1800) {
            $this->logout();
            return false;
        }

        // 验证 IP 和 User-Agent（防止会话劫持）
        if ($_SESSION['ip_address'] !== $this->getClientIP() ||
            $_SESSION['user_agent'] !== $_SERVER['HTTP_USER_AGENT']) {
            $this->logout();
            return false;
        }

        return true;
    }

    /**
     * 获取当前登录用户名
     */
    public function getCurrentUser() {
        return $_SESSION['username'] ?? null;
    }

    // ==================== 私有方法 ====================

    private function validateInput($username, $password) {
        return !empty($username) && !empty($password) &&
               strlen($username) <= 50 && strlen($password) <= 100 &&
               preg_match('/^[a-zA-Z0-9_]+$/', $username);
    }

    private function getClientIP() {
        return $_SERVER['REMOTE_ADDR'] ?? '0.0.0.0';
    }

    private function getAttemptKey($username) {
        return 'login_attempts_' . md5($username);
    }

    private function isLockedOut($username) {
        $key = $this->getAttemptKey($username);
        $attempts = $_SESSION[$key] ?? ['count' => 0, 'time' => 0];

        if ($attempts['count'] >= $this->maxLoginAttempts) {
            if (time() - $attempts['time'] < $this->lockoutTime) {
                return true;
            }
            $this->resetLoginAttempts($username);
        }
        return false;
    }

    private function recordFailedAttempt($username) {
        $key = $this->getAttemptKey($username);
        $attempts = $_SESSION[$key] ?? ['count' => 0, 'time' => 0];

        if (time() - $attempts['time'] > $this->lockoutTime) {
            $attempts = ['count' => 0, 'time' => time()];
        }

        $attempts['count']++;
        $attempts['time'] = time();
        $_SESSION[$key] = $attempts;
    }

    private function resetLoginAttempts($username) {
        unset($_SESSION[$this->getAttemptKey($username)]);
    }
}

// ==================== 使用示例 ====================

$auth = new AuthSystem();

// 登录示例
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['action'])) {
    if ($_POST['action'] === 'login') {
        $result = $auth->login($_POST['username'] ?? '', $_POST['password'] ?? '');
        echo json_encode($result);
    } elseif ($_POST['action'] === 'logout') {
        $result = $auth->logout();
        echo json_encode($result);
    }
}

// 检查登录状态
if ($auth->isLoggedIn()) {
    echo "欢迎，" . htmlspecialchars($auth->getCurrentUser()) . "！";
    echo "<br><a href='?action=logout'>登出</a>";
} else {
    echo "未登录状态";
}
?>
