```php
<?php
/**
 * 安全的支付 iframe 嵌入类
 * 版本：2.0
 * 安全等级：生产环境可用
 */

class SecurePaymentIframe {

    // 可信支付提供商白名单
    private const TRUSTED_PAYMENT_PROVIDERS = [
        'stripe' => 'https://checkout.stripe.com',
        'paypal' => 'https://www.paypal.com',
        'alipay' => 'https://openapi.alipay.com',
        'wechat' => 'https://wx.tenpay.com',
        // 添加更多可信支付网关
    ];

    // 允许的 iframe 权限
    private const IFRAME_SANDBOX = [
        'allow-forms',
        'allow-scripts',
        'allow-same-origin',
        'allow-popups',
        'allow-popups-to-escape-sandbox',
        'allow-top-navigation-by-user-activation'
    ];

    /**
     * 验证支付提供商 URL 是否在白名单中
     */
    private function validatePaymentUrl(string $url): bool {
        if (empty($url)) {
            return false;
        }

        // 必须是 HTTPS
        if (!str_starts_with($url, 'https://')) {
            return false;
        }

        // 检查是否匹配白名单中的任一提供商
        foreach (self::TRUSTED_PAYMENT_PROVIDERS as $provider => $baseUrl) {
            if (str_starts_with($url, $baseUrl)) {
                return true;
            }
        }

        return false;
    }

    /**
     * 设置安全响应头
     */
    private function setSecurityHeaders(): void {
        // 防止点击劫持
        header('X-Frame-Options: SAMEORIGIN');

        // 内容安全策略 - 限制 iframe 源
        $cspAllowedSources = implode(' ', array_values(self::TRUSTED_PAYMENT_PROVIDERS));
        header("Content-Security-Policy: frame-src $cspAllowedSources; child-src $cspAllowedSources");

        // 防止 MIME 类型嗅探
        header('X-Content-Type-Options: nosniff');

        // 启用 XSS 保护
        header('X-XSS-Protection: 1; mode=block');

        // 严格传输安全
        header('Strict-Transport-Security: max-age=31536000; includeSubDomains');

        // 限制 referrer 信息
        header('Referrer-Policy: strict-origin-when-cross-origin');
    }

    /**
     * 生成安全的 iframe HTML
     */
    private function generateIframeHtml(string $url, string $paymentId): string {
        $sandbox = implode(' ', self::IFRAME_SANDBOX);
        $uniqueId = 'payment-frame-' . htmlspecialchars($paymentId, ENT_QUOTES, 'UTF-8');
        $safeUrl = htmlspecialchars($url, ENT_QUOTES, 'UTF-8');

        return <<<HTML
        <div class="payment-container" style="position: relative; max-width: 800px; margin: 0 auto;">
            <iframe 
                id="$uniqueId"
                src="$safeUrl" 
                width="100%" 
                height="600"
                sandbox="$sandbox"
                allow="payment; clipboard-write"
                frameborder="0"
                scrolling="no"
                title="Secure Payment Gateway"
                referrerpolicy="strict-origin-when-cross-origin"
                onload="this.style.opacity='1'"
                style="opacity: 0; transition: opacity 0.3s ease; border: 1px solid #e0e0e0; border-radius: 8px;"
            ></iframe>
            <div class="loading-indicator" style="position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);">
                正在加载安全支付页面...
            </div>
        </div>
        HTML;
    }

    /**
     * 记录支付 iframe 加载日志
     */
    private function logPaymentAttempt(string $paymentId, string $provider, bool $success): void {
        $logEntry = [
            'timestamp' => date('Y-m-d H:i:s'),
            'payment_id' => $paymentId,
            'provider' => $provider,
            'success' => $success,
            'ip' => $_SERVER['REMOTE_ADDR'] ?? 'unknown',
            'user_agent' => $_SERVER['HTTP_USER_AGENT'] ?? 'unknown'
        ];

        // 生产环境应写入日志文件或数据库
        error_log('Payment Iframe: ' . json_encode($logEntry));
    }

    /**
     * 主方法：安全地嵌入支付 iframe
     * 
     * @param string $paymentUrl 支付页面 URL
     * @param string $paymentId 支付订单 ID
     * @param string $provider 支付提供商标识
     * @return string HTML 内容或错误信息
     */
    public function embed(string $paymentUrl, string $paymentId, string $provider = 'unknown'): string {
        try {
            // 1. 设置安全头
            $this->setSecurityHeaders();

            // 2. 验证支付 URL
            if (!$this->validatePaymentUrl($paymentUrl)) {
                $this->logPaymentAttempt($paymentId, $provider, false);
                throw new Exception('无效的支付网关 URL');
            }

            // 3. 验证支付 ID 格式（防止注入）
            if (!preg_match('/^[a-zA-Z0-9_-]+$/', $paymentId)) {
