            // 5. 生成安全的 iframe
            return $this->generateIframeHtml($paymentUrl, $paymentId);

        } catch (Exception $e) {
            // 生产环境不要暴露详细错误信息
            error_log('Payment Iframe Error: ' . $e->getMessage());
            return '<div class="payment-error" style="color: #d32f2f; padding: 20px; text-align: center;">
