## 修复后的完整代码

```php
<?php
// 配置数据库连接参数
define('DB_HOST', 'localhost');
define('DB_USER', 'your_username');
define('DB_PASS', 'your_password');
define('DB_NAME', 'your_database');

// 创建数据库连接
function getDbConnection() {
    $conn = new mysqli(DB_HOST, DB_USER, DB_PASS, DB_NAME);

    if ($conn->connect_error) {
        error_log("Database connection failed: " . $conn->connect_error);
        return null;
    }

    $conn->set_charset("utf8mb4");
    return $conn;
}

// 验证用户名
function validateUsername($username) {
    if (empty($username)) {
        return ['valid' => false, 'message' => '用户名不能为空'];
    }

    if (strlen($username) < 3 || strlen($username) > 50) {
        return ['valid' => false, 'message' => '用户名长度必须在3-50个字符之间'];
    }

    if (!preg_match('/^[a-zA-Z0-9_]+$/', $username)) {
        return ['valid' => false, 'message' => '用户名只能包含字母、数字和下划线'];
    }

    return ['valid' => true, 'message' => ''];
}

// 验证密码
function validatePassword($password) {
    if (empty($password)) {
        return ['valid' => false, 'message' => '密码不能为空'];
    }

    if (strlen($password) < 8) {
        return ['valid' => false, 'message' => '密码长度至少8个字符'];
    }

    if (!preg_match('/[A-Z]/', $password) || !preg_match('/[a-z]/', $password) || !preg_match('/[0-9]/', $password)) {
        return ['valid' => false, 'message' => '密码必须包含大小写字母和数字'];
    }

    return ['valid' => true, 'message' => ''];
}

// 检查用户名是否已存在
function usernameExists($conn, $username) {
    $stmt = $conn->prepare("SELECT id FROM users WHERE username = ?");
    $stmt->bind_param("s", $username);
    $stmt->execute();
    $result = $stmt->get_result();
    $exists = $result->num_rows > 0;
    $stmt->close();
    return $exists;
}

// 注册用户
function registerUser($username, $password) {
    $conn = getDbConnection();

    if (!$conn) {
        return ['success' => false, 'message' => '系统错误，请稍后重试'];
    }

    // 验证输入
    $usernameValidation = validateUsername($username);
    if (!$usernameValidation['valid']) {
        $conn->close();
        return ['success' => false, 'message' => $usernameValidation['message']];
    }

    $passwordValidation = validatePassword($password);
    if (!$passwordValidation['valid']) {
        $conn->close();
        return ['success' => false, 'message' => $passwordValidation['message']];
    }

    // 检查用户名是否已存在
    if (usernameExists($conn, $username)) {
        $conn->close();
        return ['success' => false, 'message' => '用户名已存在'];
    }

    // 密码加密
    $hashedPassword = password_hash($password, PASSWORD_DEFAULT);

    // 使用预处理语句防止SQL注入
    $stmt = $conn->prepare("INSERT INTO users (username, password, created_at) VALUES (?, ?, NOW())");

    if (!$stmt) {
        error_log("Prepare failed: " . $conn->error);
        $conn->close();
        return ['success' => false, 'message' => '系统错误，请稍后重试'];
    }

    $stmt->bind_param("ss", $username, $hashedPassword);

    if ($stmt->execute()) {
        $userId = $stmt->insert_id;
        $stmt->close();
        $conn->close();
        return ['success' => true, 'message' => '注册成功', 'user_id' => $userId];
    } else {
        error_log("Registration failed: " . $stmt->error);
        $stmt->close();
        $conn->close();
        return ['success' => false, 'message' => '注册失败，请稍后重试'];
    }
}

