```php
<?php
/**
 * 安全的文件上传处理类
 */
class FileUploader {
    // 允许的文件类型配置
    private $allowedTypes = [
        'image' => ['jpg', 'jpeg', 'png', 'gif', 'webp'],
        'document' => ['pdf', 'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx', 'txt'],
        'video' => ['mp4', 'avi', 'mov', 'wmv', 'flv'],
        'audio' => ['mp3', 'wav', 'ogg']
    ];

    // 最大文件大小（10MB）
    private $maxFileSize = 10485760;

    // 上传目录
    private $uploadDir = 'uploads/';

    // 错误消息
    private $errorMessage = '';

    /**
     * 生成唯一的文件名
     */
    public function generateUniqueFileName($originalFileName) {
        $extension = strtolower(pathinfo($originalFileName, PATHINFO_EXTENSION));
        $uniqueName = bin2hex(random_bytes(16)) . '_' . time() . '.' . $extension;
        return $uniqueName;
    }

    /**
     * 验证文件类型
     */
    private function validateFileType($fileName, $fileType) {
        $extension = strtolower(pathinfo($fileName, PATHINFO_EXTENSION));

        foreach ($this->allowedTypes as $type => $extensions) {
            if (in_array($extension, $extensions)) {
                return true;
            }
        }

        $this->errorMessage = '不允许的文件类型';
        return false;
    }

    /**
     * 验证文件大小
     */
    private function validateFileSize($fileSize) {
        if ($fileSize > $this->maxFileSize) {
            $this->errorMessage = '文件大小超过限制（最大10MB）';
            return false;
        }
        return true;
    }

    /**
     * 验证MIME类型
     */
    private function validateMimeType($tmpName, $extension) {
        $finfo = finfo_open(FILEINFO_MIME_TYPE);
        $mimeType = finfo_file($finfo, $tmpName);
        finfo_close($finfo);

        $allowedMimeTypes = [
            'image/jpeg', 'image/png', 'image/gif', 'image/webp',
            'application/pdf', 'application/msword',
            'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
            'video/mp4', 'audio/mpeg'
        ];

        if (!in_array($mimeType, $allowedMimeTypes)) {
            $this->errorMessage = '文件MIME类型不被允许';
            return false;
        }

        return true;
    }

    /**
     * 确保上传目录存在
     */
    private function ensureUploadDir() {
        if (!file_exists($this->uploadDir)) {
            if (!mkdir($this->uploadDir, 0755, true)) {
                $this->errorMessage = '无法创建上传目录';
                return false;
            }
        }

        if (!is_writable($this->uploadDir)) {
            $this->errorMessage = '上传目录不可写';
            return false;
        }

        return true;
    }

    /**
     * 处理文件上传
     */
    public function upload($file) {
        // 检查上传错误
        if ($file['error'] !== UPLOAD_ERR_OK) {
            $this->errorMessage = $this->getUploadErrorMessage($file['error']);
            return false;
        }

        // 验证文件大小
        if (!$this->validateFileSize($file['size'])) {
            return false;
        }

        // 验证文件类型
        if (!$this->validateFileType($file['name'], $file['type'])) {
            return false;
        }

        // 验证MIME类型
        if (!$this->validateMimeType($file['tmp_name'], pathinfo($file['name'], PATHINFO_EXTENSION))) {
            return false;
        }

        // 确保上传目录存在
        if (!$this->ensureUploadDir()) {
            return false;
        }

        // 生成唯一文件名
        $uniqueFileName = $this->generateUniqueFileName($file['name']);
        $destination = $this->uploadDir . $uniqueFileName;

        // 移动上传的文件
        if (!move_uploaded_file($file['tmp_name'], $destination)) {
            $this->errorMessage = '文件移动失败';
            return false;
        }

        // 设置文件权限
        chmod($destination, 0644);

        return [
            'success' => true,
            'fileName' => $uniqueFileName,
            'filePath' => $destination,
            'fileSize' => $file['size'],
            'fileType' => $file['type']
        ];
    }

    /**
     * 获取上传错误消息
     */
    private function getUploadErrorMessage($errorCode) {
        $errors = [
            UPLOAD_ERR_INI_SIZE => '文件超过php.ini限制',
            UPLOAD_ERR_FORM_SIZE => '文件超过表单限制',
            UPLOAD_ERR_PARTIAL => '文件上传不完整',
            UPLOAD_ERR_NO_FILE => '没有文件上传',
            UPLOAD_ERR_NO_TMP_DIR => '缺少临时目录',
            UPLOAD_ERR_CANT_WRITE => '写入失败',
            UPLOAD_ERR_EXTENSION => '扩展阻止上传'
        ];

        return $errors[$errorCode] ?? '未知上传错误';
    }

    /**
     * 获取错误消息
     */
    public function getErrorMessage() {
        return $this->errorMessage;
    }

    /**
     * 设置上传目录
     */
    public function setUploadDir($dir) {
        $this->uploadDir = rtrim($dir, '/') . '/';
    }

    /**
     * 设置最大文件大小
     */
    public function setMaxFileSize($size) {
        $this->maxFileSize = $size;
    }
}

