# 安全的文件上传实现

## ⚠️ 安全警告

原代码存在**严重安全漏洞**，允许上传任意文件类型（包括PHP脚本），可能导致**远程代码执行(RCE)**。以下是修复后的安全版本：

## 优化后的完整代码

```php
<?php
// 配置常量
define('UPLOAD_DIR', 'uploads/');
define('MAX_FILE_SIZE', 5 * 1024 * 1024); // 5MB
define('ALLOWED_TYPES', ['image/jpeg', 'image/png', 'image/gif', 'image/webp']);
define('ALLOWED_EXTENSIONS', ['jpg', 'jpeg', 'png', 'gif', 'webp']);

/**
 * 安全的图片上传函数
 */
function upload_image($file) {
    // 1. 检查上传错误
    if ($file['error'] !== UPLOAD_ERR_OK) {
        return ['success' => false, 'message' => '上传错误: ' . $file['error']];
    }

    // 2. 验证文件大小
    if ($file['size'] > MAX_FILE_SIZE) {
        return ['success' => false, 'message' => '文件过大，最大5MB'];
    }

    // 3. 验证MIME类型（使用finfo，不信任客户端）
    $finfo = new finfo(FILEINFO_MIME_TYPE);
    $mime_type = $finfo->file($file['tmp_name']);

    if (!in_array($mime_type, ALLOWED_TYPES)) {
        return ['success' => false, 'message' => '不允许的文件类型'];
    }

    // 4. 验证文件扩展名
    $extension = strtolower(pathinfo($file['name'], PATHINFO_EXTENSION));
    if (!in_array($extension, ALLOWED_EXTENSIONS)) {
        return ['success' => false, 'message' => '不允许的文件扩展名'];
    }

    // 5. 验证是否为真实图片
    $image_info = getimagesize($file['tmp_name']);
    if ($image_info === false) {
        return ['success' => false, 'message' => '不是有效的图片文件'];
    }

    // 6. 生成安全的文件名（防止路径遍历和覆盖）
    $safe_filename = bin2hex(random_bytes(16)) . '.' . $extension;
    $target_dir = UPLOAD_DIR;

    // 确保上传目录存在且不可执行
    if (!is_dir($target_dir)) {
        mkdir($target_dir, 0755, true);
    }

    // 7. 创建.htaccess防止PHP执行（Apache）
    $htaccess_path = $target_dir . '.htaccess';
    if (!file_exists($htaccess_path)) {
        file_put_contents($htaccess_path, "php_flag engine off\nOptions -ExecCGI\nRemoveHandler .php .phtml .php3 .php4 .php5 .php7 .phps");
    }

    $target_file = $target_dir . $safe_filename;

    // 8. 移动上传文件
    if (move_uploaded_file($file['tmp_name'], $target_file)) {
        // 9. 设置文件权限
        chmod($target_file, 0644);

        return [
            'success' => true, 
            'message' => '上传成功',
            'filename' => $safe_filename,
            'path' => $target_file
        ];
    }

    return ['success' => false, 'message' => '文件移动失败'];
}

/**
 * 安全的测试函数（仅用于测试合法图片）
 */
function test_upload($file_path) {
    // 创建测试图片（GD库生成，确保是真实图片）
    $image = imagecreatetruecolor(100, 100);
    $white = imagecolorallocate($image, 255, 255, 255);
    imagefill($image, 0, 0, $white);
    imagepng($image, $file_path);
    imagedestroy($image);

    $file = [
        'name' => 'test_image.png',
        'tmp_name' => $file_path,
        'size' => filesize($file_path),
        'error' => UPLOAD_ERR_OK,
        'type' => 'image/png'
    ];

    $result = upload_image($file);
    echo json_encode($result, JSON_PRETTY_PRINT);

    // 清理测试文件
    if (file_exists($file_path)) {
        unlink($file_path);
    }
}

// 使用示例
