以下是一个完整、可运行的 Airbnb 风格短租平台搜索功能实现，使用 PHP + MySQL，包含数据库结构、安全搜索逻辑、前端表单和结果展示，并附有优化说明。

---

## 1. 数据库表结构（MySQL）

```sql
CREATE TABLE listings (
    id INT AUTO_INCREMENT PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    description TEXT,
    location VARCHAR(255) NOT NULL,
    price_per_night DECIMAL(10,2) NOT NULL,
    max_guests INT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_location (location),
    INDEX idx_price (price_per_night)
);

CREATE TABLE bookings (
    id INT AUTO_INCREMENT PRIMARY KEY,
    listing_id INT NOT NULL,
    check_in DATE NOT NULL,
    check_out DATE NOT NULL,
    guest_name VARCHAR(255),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (listing_id) REFERENCES listings(id) ON DELETE CASCADE,
    INDEX idx_listing_dates (listing_id, check_in, check_out)
);
```

---

## 2. 数据库连接配置（config.php）

```php
<?php
define('DB_HOST', 'localhost');
define('DB_NAME', 'airbnb_clone');
define('DB_USER', 'root');
define('DB_PASS', '');

function getDBConnection() {
    try {
        $pdo = new PDO(
            "mysql:host=" . DB_HOST . ";dbname=" . DB_NAME . ";charset=utf8mb4",
            DB_USER,
            DB_PASS,
            [
                PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
                PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
                PDO::ATTR_EMULATE_PREPARES => false
            ]
        );
        return $pdo;
    } catch (PDOException $e) {
        error_log("DB Connection Error: " . $e->getMessage());
        die("数据库连接失败，请稍后重试。");
    }
}
?>
```

---

## 3. 搜索处理逻辑（search.php）

```php
<?php
require_once 'config.php';

$errors = [];
$results = [];
$searchParams = [];

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $location = trim($_POST['location'] ?? '');
    $checkIn = $_POST['check_in'] ?? '';
    $checkOut = $_POST['check_out'] ?? '';

    // 验证
    if (empty($location)) $errors[] = "地点不能为空";
    if (!validateDate($checkIn)) $errors[] = "入住日期格式无效";
    if (!validateDate($checkOut)) $errors[] = "退房日期格式无效";
    if ($checkIn && $checkOut && strtotime($checkIn) >= strtotime($checkOut)) {
        $errors[] = "退房日期必须晚于入住日期";
    }

    if (empty($errors)) {
        $searchParams = compact('location', 'checkIn', 'checkOut');
        $results = searchListings($location, $checkIn, $checkOut);
    }
}

function validateDate($date) {
    return preg_match('/^\d{4}-\d{2}-\d{2}$/', $date) && checkdate(
        (int)substr($date, 5, 2),
        (int)substr($date, 8, 2),
        (int)substr($date, 0, 4)
    );
}

function searchListings($location, $checkIn, $checkOut) {
    $pdo = getDBConnection();
    $sql = "
        SELECT l.* 
        FROM listings l
        WHERE l.location LIKE :location
        AND l.id NOT IN (
            SELECT b.listing_id FROM bookings b
            WHERE b.check_in < :checkOut AND b.check_out > :checkIn
        )
    ";
    $stmt = $pdo->prepare($sql);
    $stmt->execute([
        ':location' => "%{$location}%",
        ':checkIn' => $checkIn,
        ':checkOut' => $checkOut
    ]);
    return $stmt->fetchAll();
}
?>
```

