</head>
<body>
    <h1>🏠 搜索可用房源</h1>

    <?php if (!empty($errors)): ?>
        <div class="error">
            <?php foreach ($errors as $e): ?>
                <p>⚠️ <?= htmlspecialchars($e) ?></p>
            <?php endforeach; ?>
        </div>
    <?php endif; ?>

    <form method="POST">
        <input type="text" name="location" placeholder="地点（如：北京）" value="<?= htmlspecialchars($searchParams['location'] ?? '') ?>" required>
        <input type="date" name="check_in" value="<?= htmlspecialchars($searchParams['checkIn'] ?? '') ?>" required>
