        <button type="submit">搜索</button>
    </form>

    <?php if (!empty($results)): ?>
        <h2>找到 <?= count($results) ?> 套可用房源</h2>
        <?php foreach ($results as $listing): ?>
            <div class="listing">
                <h3><?= htmlspecialchars($listing['title']) ?></h3>
                <p>📍 <?= htmlspecialchars($listing['location']) ?></p>
                <p>💰 ¥<?= number_format($listing['price_per_night'], 2) ?> / 晚</p>
