    public function __construct() {
        $this->key = hex2bin(getenv('ENCRYPTION_KEY') ?: '0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef');
        $this->hmacKey = getenv('HMAC_KEY') ?: 'secure_hmac_key_change_in_production';
    }

    public function encrypt($data) {
        $iv = openssl_random_pseudo_bytes(16);
        $encrypted = openssl_encrypt($data, $this->cipher, $this->key, OPENSSL_RAW_DATA, $iv);
        if ($encrypted === false) {
            throw new Exception('Encryption failed: ' . openssl_error_string());
        }

        $hmac = hash_hmac('sha256', $iv . $encrypted, $this->hmacKey, true);
        return base64_encode($hmac . $iv . $encrypted);
    }

    public function decrypt($payload) {
        $decoded = base64_decode($payload, true);
        if ($decoded === false || strlen($decoded) < 49) {
            throw new Exception('Invalid payload format');
        }

        $hmac = substr($decoded, 0, 32);
        $iv = substr($decoded, 32, 16);
        $ciphertext = substr($decoded, 48);

        $expectedHmac = hash_hmac('sha256', $iv . $ciphertext, $this->hmacKey, true);
        if (!hash_equals($expectedHmac, $hmac)) {
            throw new Exception('HMAC verification failed');
        }

        $decrypted = openssl_decrypt($ciphertext, $this->cipher, $this->key, OPENSSL_RAW_DATA, $iv);
        if ($decrypted === false) {
            throw new Exception('Decryption failed: ' . openssl_error_string());
        }

        return $decrypted;
    }
}
