<?php
// 安全的资源加载示例

class SecureResourceLoader {
    // 白名单域名
    private static $allowedDomains = [
        'https://cdn.jsdelivr.net',
        'https://unpkg.com',
        'https://cdnjs.cloudflare.com'
    ];

    // SRI 哈希值（必须验证）
    private static $sriHashes = [
        'jquery-3.6.0.min.js' => 'sha384-vtXRMe3mGCbOeY7l30aIg8H9p3GdeSe4IFlP6G8JMa7o7lXvnz3GFKzPxzJdPfGK',
        'bootstrap.min.css' => 'sha384-EVSTQN3/azprG1Anm3QDgpJLIm9Nao0Yz1ztcQTwFspd3yD65VohhpuuCOmLASjC'
    ];

    public static function loadScript($url, $sriHash) {
        // 验证域名
        if (!self::validateDomain($url)) {
            error_log("Blocked untrusted domain: $url");
            return '';
        }

        // 验证 SRI
        if (!self::validateSRI($url, $sriHash)) {
            error_log("SRI validation failed: $url");
            return '';
        }

        return sprintf(
            '<script src="%s" integrity="%s" crossorigin="anonymous"></script>',
            htmlspecialchars($url, ENT_QUOTES, 'UTF-8'),
            htmlspecialchars($sriHash, ENT_QUOTES, 'UTF-8')
        );
    }

    private static function validateDomain($url) {
        $parsed = parse_url($url);
        $domain = $parsed['scheme'] . '://' . $parsed['host'];
        return in_array($domain, self::$allowedDomains);
    }

    private static function validateSRI($url, $hash) {
        // 生产环境应该验证实际文件哈希
        return !empty($hash) && strpos($hash, 'sha384-') === 0;
    }
}

// 使用示例
