const express = require('express');
const sanitizeHtml = require('sanitize-html');
const path = require('path');

const app = express();
const PORT = 3000;

app.use(express.json());
app.use(express.static('public'));

// 模拟知识库解答（实际可对接AI API）
const knowledgeBase = {
  '课程': '我们提供K12全学科课程，包括数学、英语、物理等...',
  '价格': '课程价格从99元/月起，具体请咨询客服...',
  '老师': '所有老师均持有教师资格证，平均教龄5年以上...',
  '默认': '感谢您的咨询！我们的教育顾问将在24小时内联系您。'
};

// 生成智能回复
function generateResponse(question) {
  for (const [keyword, answer] of Object.entries(knowledgeBase)) {
    if (question.includes(keyword)) {
      return answer;
    }
  }
  return knowledgeBase['默认'];
}

// 提交咨询接口
app.post('/api/consult', (req, res) => {
  const { question } = req.body;

  if (!question || question.trim().length === 0) {
    return res.status(400).json({ 
      success: false, 
      error: '问题不能为空' 
    });
  }

  if (question.length > 500) {
    return res.status(400).json({ 
      success: false, 
      error: '问题长度不能超过500字' 
    });
  }

  // 安全过滤HTML（防止XSS攻击）
  const cleanQuestion = sanitizeHtml(question, {
    allowedTags: ['b', 'i', 'em', 'strong', 'a', 'p', 'br'],
    allowedAttributes: {
      'a': ['href', 'target']
    },
    allowedSchemes: ['http', 'https', 'mailto']
  });

  const answer = generateResponse(cleanQuestion);
  const timestamp = new Date().toISOString();

  res.json({
    success: true,
    data: {
      question: cleanQuestion,
      answer: answer,
      timestamp: timestamp,
      consultationId: `CONS-${Date.now()}`
    }
  });
});

app.listen(PORT, () => {
  console.log(`🎓 教育咨询平台运行在 http://localhost:${PORT}`);
});
