## ✅ 推荐方案：PHP原生日志（与您的技术栈匹配）

```php
<?php
// config/logging.php
class PaymentLogger {
    private $logFile;
    private $minLevel = 'INFO';

    public function __construct($logFile = 'payment_transactions.log') {
        $this->logFile = $logFile;
        // 设置安全的文件权限
        if (!file_exists($logFile)) {
            touch($logFile);
            chmod($logFile, 0640); // 仅所有者和组可读写
        }
    }

    public function logPayment($userId, $amount, $paymentMethod, $transactionId = null) {
        $timestamp = date('Y-m-d H:i:s');
        $transactionId = $transactionId ?: uniqid('txn_', true);

        // 敏感信息脱敏
        $maskedMethod = $this->maskPaymentMethod($paymentMethod);

        $logEntry = sprintf(
            "[%s] [INFO] [TXN:%s] User:%s | Amount:$%.2f | Method:%s | IP:%s\n",
            $timestamp,
            $transactionId,
            $this->sanitize($userId),
            $amount,
            $maskedMethod,
            $_SERVER['REMOTE_ADDR'] ?? 'unknown'
        );

        // 原子写入（防止并发问题）
        file_put_contents($this->logFile, $logEntry, FILE_APPEND | LOCK_EX);

        return $transactionId;
    }

    private function maskPaymentMethod($method) {
        // 如果是卡号，只保留后4位
        if (preg_match('/^\d{13,19}$/', $method)) {
            return '****-****-****-' . substr($method, -4);
        }
        return $method;
    }

    private function sanitize($input) {
        return htmlspecialchars(strip_tags($input), ENT_QUOTES, 'UTF-8');
    }
}

// 使用示例
$logger = new PaymentLogger('/var/log/payments/transactions.log');
$txnId = $logger->logPayment(12345, 100.00, 'Credit Card');
echo "Transaction logged: $txnId\n";
?>
