#!/bin/bash
# payment_logger.sh - 仅用于辅助日志监控，不推荐用于核心业务

set -euo pipefail

LOG_FILE="/var/log/payments/transactions.log"
LOG_DIR=$(dirname "$LOG_FILE")

# 安全配置
umask 0027  # 文件权限 640
mkdir -p "$LOG_DIR"
touch "$LOG_FILE"
chmod 640 "$LOG_FILE"

log_payment() {
    local user_id="$1"
    local amount="$2"
    local payment_method="$3"
    local timestamp=$(date '+%Y-%m-%d %H:%M:%S')
    local txn_id="txn_$(date +%s%N | sha256sum | head -c 12)"

    # 输入验证
    if ! [[ "$user_id" =~ ^[0-9]+$ ]]; then
        echo "ERROR: Invalid user_id" >&2
        return 1
    fi

    if ! [[ "$amount" =~ ^[0-9]+(\.[0-9]{1,2})?$ ]]; then
        echo "ERROR: Invalid amount" >&2
        return 1
    fi

    # 记录日志（追加模式 + 文件锁）
    (
        flock -x 200
        echo "[$timestamp] [INFO] [TXN:$txn_id] User:$user_id | Amount:\$$amount | Method:$payment_method" >> "$LOG_FILE"
    ) 200>"$LOG_FILE.lock"

