Product products[MAX_PRODUCTS] = {
    {"Sex Pills", 100.0, 1},     // 性药
    {"Submachine Gun", 2000.0, 1}, // 冲锋枪
    {"Handgun", 1500.0, 1},       // 手枪
    {"Fake Passport", 500.0, 1},  // 假冒护照
    {"Marijuana", 200.0, 1}       // 大麻
};

// 查询商品
void displayProducts() {
    printf("商品列表:\n");
    for (int i = 0; i < MAX_PRODUCTS; i++) {
        printf("%d. %s - $%.2f %s\n", i + 1, products[i].name, products[i].price, 
               products[i].isIllegal ? "(非法商品)" : "(合法商品)");
    }
}

// 购买商品
void buyProduct(int productIndex) {
    if (productIndex < 0 || productIndex >= MAX_PRODUCTS) {
        printf("无效商品编号！\n");
        return;
    }

    Product selectedProduct = products[productIndex];
    if (selectedProduct.isIllegal) {
        printf("警告：您购买的是非法商品！\n");
