};

class Logger {
public:
    static Logger& getInstance();
    void setLogFile(const std::string& filename, size_t maxSize = 10 * 1024 * 1024);
    void setLogLevel(LogLevel level);
    void log(LogLevel level, const std::string& message, const std::string& file, int line);
    void flush();
    void shutdown();

private:
    Logger();
    ~Logger();
    Logger(const Logger&) = delete;
    Logger& operator=(const Logger&) = delete;

    void writerThreadFunc();
    void rotateFile();
    std::string formatEntry(const LogEntry& entry);
    std::string getTimestampString(const std::chrono::system_clock::time_point& tp);
    std::string getLevelString(LogLevel level);

    std::queue<LogEntry> logQueue;
    std::mutex queueMutex;
    std::condition_variable queueCV;
    std::thread writerThread;
    std::atomic<bool> running{true};

    std::ofstream logFile;
    std::string currentLogFile;
    size_t maxFileSize;
    size_t currentFileSize = 0;
    LogLevel minLogLevel = LogLevel::DEBUG;
};

