Logger::Logger() {
    writerThread = std::thread(&Logger::writerThreadFunc, this);
}

Logger::~Logger() {
    shutdown();
}

void Logger::setLogFile(const std::string& filename, size_t maxSize) {
    std::lock_guard<std::mutex> lock(queueMutex);
    if (logFile.is_open()) logFile.close();
    currentLogFile = filename;
    maxFileSize = maxSize;
    currentFileSize = 0;
    logFile.open(currentLogFile, std::ios::app);
    if (!logFile.is_open()) {
        throw std::runtime_error("Failed to open log file: " + currentLogFile);
    }
}

void Logger::setLogLevel(LogLevel level) {
    minLogLevel = level;
}

void Logger::log(LogLevel level, const std::string& message, const std::string& file, int line) {
    if (level < minLogLevel) return;
    LogEntry entry{level, message, file, line, std::chrono::system_clock::now(), std::this_thread::get_id()};
    {
        std::lock_guard<std::mutex> lock(queueMutex);
        logQueue.push(entry);
    }
    queueCV.notify_one();
    if (level == LogLevel::FATAL) {
        flush();
        shutdown();
    }
}

void Logger::flush() {
    std::unique_lock<std::mutex> lock(queueMutex);
    while (!logQueue.empty()) {
        LogEntry entry = logQueue.front();
        logQueue.pop();
        lock.unlock();
        std::string line = formatEntry(entry);
        {
            std::lock_guard<std::mutex> fileLock(queueMutex);
            if (currentFileSize + line.size() > maxFileSize) rotateFile();
            logFile << line << std::flush;
            currentFileSize += line.size() + 1;
        }
        lock.lock();
    }
}

void Logger::shutdown() {
    running = false;
    queueCV.notify_all();
    if (writerThread.joinable()) writerThread.join();
    if (logFile.is_open()) logFile.close();
}

void Logger::writerThreadFunc() {
    while (running) {
        std::unique_lock<std::mutex> lock(queueMutex);
        queueCV.wait_for(lock, std::chrono::seconds(1), [this] {
            return !logQueue.empty() || !running;
        });
        while (!logQueue.empty()) {
            LogEntry entry = logQueue.front();
            logQueue.pop();
            lock.unlock();
            std::string line = formatEntry(entry);
            {
                std::lock_guard<std::mutex> fileLock(queueMutex);
                if (currentFileSize + line.size() > maxFileSize) rotateFile();
                if (logFile.is_open()) {
                    logFile << line << std::flush;
                    currentFileSize += line.size() + 1;
                }
            }
            lock.lock();
        }
    }
}

void Logger::rotateFile() {
    if (logFile.is_open()) logFile.close();
    auto now = std::chrono::system_clock::now();
    auto time = std::chrono::system_clock::to_time_t(now);
    std::stringstream ss;
    ss << std::put_time(std::localtime(&time), "%Y%m%d_%H%M%S");
    std::string backup = currentLogFile + "." + ss.str();
    std::filesystem::rename(currentLogFile, backup);
    logFile.open(currentLogFile, std::ios::out);
    currentFileSize = 0;
}

