// HTML转义函数 - 防止XSS攻击
std::string escapeHTML(const std::string& input) {
    std::string output;
    for (char c : input) {
        switch (c) {
            case '&': output += "&amp;"; break;
            case '<': output += "&lt;"; break;
            case '>': output += "&gt;"; break;
            case '"': output += "&quot;"; break;
            case '\'': output += "&#x27;"; break;
            default: output += c;
        }
    }
    return output;
}

// 允许的安全HTML标签白名单
std::string sanitizeHTML(const std::string& input) {
    // 只允许特定的安全标签
    std::regex safeTags("<(a|b|i|strong|em|br|p)[^>]*>|</(a|b|i|strong|em|p)>");
    std::string result = input;

    // 移除所有不允许的标签
    std::regex allTags("<[^>]+>");
    std::smatch match;
    std::string temp;

    auto begin = std::sregex_iterator(result.begin(), result.end(), allTags);
    auto end = std::sregex_iterator();

    size_t lastPos = 0;
    for (auto i = begin; i != end; ++i) {
        match = *i;
        temp += result.substr(lastPos, match.position() - lastPos);

        if (std::regex_match(match.str(), safeTags)) {
            // 检查a标签的href是否安全
            if (match.str().find("<a") != std::string::npos) {
                if (match.str().find("javascript:") == std::string::npos &&
                    match.str().find("data:") == std::string::npos) {
                    temp += match.str();
                }
            } else {
                temp += match.str();
            }
        }
        lastPos = match.position() + match.length();
    }
    temp += result.substr(lastPos);

    return temp;
}

// SHA256密码哈希
std::string hashPassword(const std::string& password) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, password.c_str(), password.size());
    SHA256_Final(hash, &sha256);

    std::stringstream ss;
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        ss << std::hex << std::setw(2) << std::setfill('0') << (int)hash[i];
    }
    return ss.str();
}

