    if (!DB || question.empty()) {
        return false;
    }

    // 对用户输入进行安全处理
    std::string safeQuestion = sanitizeHTML(escapeHTML(question));

    // 使用参数化查询防止SQL注入
    const char* sql = "INSERT INTO questions (username, question, status, created_at) "
                      "VALUES (?, ?, 'pending', datetime('now'))";

    sqlite3_stmt* stmt;
    if (sqlite3_prepare_v2(DB, sql, -1, &stmt, nullptr) != SQLITE_OK) {
        std::cerr << "SQL准备失败: " << sqlite3_errmsg(DB) << std::endl;
        return false;
    }

    sqlite3_bind_text(stmt, 1, username.c_str(), -1, SQLITE_STATIC);
    sqlite3_bind_text(stmt, 2, safeQuestion.c_str(), -1, SQLITE_STATIC);

    if (sqlite3_step(stmt) == SQLITE_DONE) {
        questionId = sqlite3_last_insert_rowid(DB);
        sqlite3_finalize(stmt);
        return true;
    }

    std::cerr << "插入失败: " << sqlite3_errmsg(DB) << std::endl;
    sqlite3_finalize(stmt);
    return false;
}

