以下是优化后的完整 C++ 日志管理工具代码，包含日志读取、存储及管理功能，结构清晰、可运行、易扩展。

```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <string>
#include <chrono>
#include <iomanip>
#include <algorithm>
#include <memory>

// 日志级别枚举
enum class LogLevel {
    DEBUG,
    INFO,
    WARNING,
    ERROR,
    CRITICAL
};

// 日志条目结构
struct LogEntry {
    std::string timestamp;
    LogLevel level;
    std::string message;
    std::string source;

    std::string levelToString() const {
        switch (level) {
            case LogLevel::DEBUG: return "DEBUG";
            case LogLevel::INFO: return "INFO";
            case LogLevel::WARNING: return "WARNING";
            case LogLevel::ERROR: return "ERROR";
            case LogLevel::CRITICAL: return "CRITICAL";
            default: return "UNKNOWN";
        }
    }

    std::string toString() const {
        return "[" + timestamp + "] [" + levelToString() + "] [" + source + "] " + message;
    }
};

// 日志管理器类
class LogManager {
private:
    std::vector<LogEntry> entries;
    std::string logFilePath;

    std::string getCurrentTimestamp() {
        auto now = std::chrono::system_clock::now();
        auto time = std::chrono::system_clock::to_time_t(now);
        std::stringstream ss;
        ss << std::put_time(std::localtime(&time), "%Y-%m-%d %H:%M:%S");
        return ss.str();
    }

    LogLevel parseLogLevel(const std::string& levelStr) {
        if (levelStr == "DEBUG") return LogLevel::DEBUG;
        if (levelStr == "INFO") return LogLevel::INFO;
        if (levelStr == "WARNING") return LogLevel::WARNING;
        if (levelStr == "ERROR") return LogLevel::ERROR;
        if (levelStr == "CRITICAL") return LogLevel::CRITICAL;
        return LogLevel::INFO;
    }

public:
    explicit LogManager(const std::string& filePath = "application.log")
        : logFilePath(filePath) {}

    // 读取单条日志字符串
    void readLogEntry(const std::string& logEntry) {
        if (logEntry.empty()) return;

        LogEntry entry;
        std::istringstream iss(logEntry);
        std::string token;

        // 解析时间戳 [YYYY-MM-DD HH:MM:SS]
        if (logEntry[0] == '[') {
            size_t end = logEntry.find(']');
            if (end != std::string::npos) {
                entry.timestamp = logEntry.substr(1, end - 1);
                iss.str(logEntry.substr(end + 1));
                iss.clear();
            }
        }

        // 解析日志级别 [LEVEL]
        if (iss >> token && token[0] == '[') {
            size_t end = token.find(']');
            if (end != std::string::npos) {
                entry.level = parseLogLevel(token.substr(1, end - 1));
            }
        }

        // 解析来源 [source]
        if (iss >> token && token[0] == '[') {
            size_t end = token.find(']');
            if (end != std::string::npos) {
                entry.source = token.substr(1, end - 1);
            }
        }

        // 剩余为消息内容
        std::getline(iss, entry.message);
        if (!entry.message.empty() && entry.message[0] == ' ') {
            entry.message = entry.message.substr(1);
        }

        if (entry.timestamp.empty()) {
            entry.timestamp = getCurrentTimestamp();
        }

        entries.push_back(entry);
    }

    // 从文件读取所有日志
    void readLogFromFile() {
        std::ifstream file(logFilePath);
        if (!file.is_open()) {
            std::cerr << "无法打开日志文件: " << logFilePath << std::endl;
            return;
        }

        std::string line;
        while (std::getline(file, line)) {
            if (!line.empty()) {
                readLogEntry(line);
            }
        }
        file.close();
    }

    // 添加新日志
    void addLogEntry(LogLevel level, const std::string& message, const std::string& source = "APP") {
        LogEntry entry;
        entry.timestamp = getCurrentTimestamp();
        entry.level = level;
        entry.message = message;
        entry.source = source;
        entries.push_back(entry);
    }

    // 保存日志到文件
    void saveLogToFile() {
        std::ofstream file(logFilePath, std::ios::app);
        if (!file.is_open()) {
            std::cerr << "无法写入日志文件: " << logFilePath << std::endl;
            return;
        }

        for (const auto& entry : entries) {
            file << entry.toString() << std::endl;
        }
        file.close();
    }

    // 按级别过滤日志
    std::vector<LogEntry> filterByLevel(LogLevel level) const {
        std::vector<LogEntry> result;
        for (const auto& entry : entries) {
            if (entry.level == level) {
                result.push_back(entry);
            }
        }
        return result;
    }

    // 按关键字搜索日志
    std::vector<LogEntry> searchByKeyword(const std::string& keyword) const {
        std::vector<LogEntry> result;
        for (const auto& entry : entries) {
            if (entry.message.find(keyword) != std::string::npos ||
                entry.source.find(keyword) != std::string::npos) {
                result.push_back(entry);
            }
        }
        return result;
    }

    // 清除所有日志
    void clearLogs() {
        entries.clear();
    }

    // 获取日志数量
    size_t getLogCount() const {
        return entries.size();
    }

    // 打印所有日志
    void displayLogs() const {
        if (entries.empty()) {
            std::cout << "暂无日志记录。" << std::endl;
            return;
        }

        std::cout << "\n=== 日志列表 (共 " << entries.size() << " 条) ===\n";
        for (size_t i = 0; i < entries.size(); ++i) {
            std::cout << "[" << i + 1 << "] " << entries[i].toString() << std::endl;
        }
        std::cout << "================================\n" << std::endl;
    }
};

// 示例主函数
int main() {
    LogManager logger("app.log");

    // 添加几条日志
    logger.addLogEntry(LogLevel::INFO, "系统启动成功", "System");
    logger.addLogEntry(LogLevel::WARNING, "内存使用率过高", "Monitor");
    logger.addLogEntry(LogLevel::ERROR, "数据库连接失败", "Database");

    // 显示日志
    logger.displayLogs();

    // 搜索包含“数据库”的日志
    auto results = logger.searchByKeyword("数据库");
    std::cout << "搜索结果（包含'数据库'）:\n";
    for (const auto& entry : results) {
        std::cout << entry.toString() << std::endl;
    }

    // 保存日志到文件
    logger.saveLogToFile();

    // 从文件重新加载日志
    logger.clearLogs();
    logger.readLogFromFile();
    logger.displayLogs();

    return 0;
}
```

