// 虚拟玩家对象
class VirtualPlayer {
public:
    int id;
    bool active;
    VirtualPlayer(int i) : id(i), active(true) {}
};

// 对象池模板
template<typename T>
class ObjectPool {
    mutex mtx;
    vector<shared_ptr<T>> pool;
public:
    shared_ptr<T> acquire(int id) {
        lock_guard<mutex> lock(mtx);
        if (!pool.empty()) {
            auto obj = pool.back();
            pool.pop_back();
            return obj;
        }
        return make_shared<T>(id);
    }
    void release(shared_ptr<T> obj) {
        lock_guard<mutex> lock(mtx);
        pool.push_back(obj);
    }
};

// 线程池
class ThreadPool {
    vector<thread> workers;
    queue<function<void()>> tasks;
    mutex queueMutex;
    condition_variable condition;
    atomic<bool> stop{false};
public:
    ThreadPool(size_t threads) {
        for (size_t i = 0; i < threads; ++i)
            workers.emplace_back([this] {
                while (true) {
                    function<void()> task;
                    {
                        unique_lock<mutex> lock(queueMutex);
                        condition.wait(lock, [this] { return stop || !tasks.empty(); });
                        if (stop && tasks.empty()) return;
                        task = move(tasks.front());
                        tasks.pop();
                    }
                    task();
                }
            });
    }
    void enqueue(function<void()> task) {
        {
            lock_guard<mutex> lock(queueMutex);
            tasks.push(move(task));
        }
        condition.notify_one();
    }
    ~ThreadPool() {
        stop = true;
        condition.notify_all();
        for (auto& w : workers) w.join();
    }
};

// 消息队列 + 限流
class MessageQueue {
    queue<Message> mq;
    mutex mtx;
    condition_variable cv;
    atomic<int> msgCount{0};
    const int MAX_MSG_PER_SEC = 1000;
    chrono::steady_clock::time_point lastReset = chrono::steady_clock::now();
public:
    void push(Message msg) {
        auto now = chrono::steady_clock::now();
        if (chrono::duration_cast<chrono::seconds>(now - lastReset).count() >= 1) {
            msgCount = 0;
            lastReset = now;
        }
        if (msgCount >= MAX_MSG_PER_SEC) return; // 限流
        {
            lock_guard<mutex> lock(mtx);
            mq.push(msg);
            ++msgCount;
        }
        cv.notify_one();
    }
    bool pop(Message& msg) {
        unique_lock<mutex> lock(mtx);
        if (mq.empty()) return false;
        msg = mq.front();
        mq.pop();
        return true;
    }
};

