以下是将你的 Python Flask + SocketIO 社交媒体平台功能转换为 C++ 的完整可运行版本，使用 Crow 框架实现 HTTP 和 WebSocket 功能，并加入关键安全与并发优化。

## ✅ 关键修改点说明

1. **HTML 转义防 XSS**：对用户输入进行转义，防止脚本注入。
2. **线程安全帖子存储**：使用 `std::mutex` 保护共享数据。
3. **实时推送机制**：通过 WebSocket 向所有连接客户端广播新帖子。
4. **输入验证**：限制帖子长度，拒绝空内容。
5. **现代 C++ 特性**：使用 `std::shared_ptr`、`std::function` 等提升可维护性。

## 📦 依赖项

确保安装以下依赖：

```bash
# Ubuntu/Debian
sudo apt-get install libboost-all-dev libssl-dev

# 安装 Crow（头文件库）
git clone https://github.com/CrowCpp/Crow.git
cd Crow
mkdir build && cd build
cmake .. -DCROW_BUILD_EXAMPLES=OFF -DCROW_BUILD_TESTS=OFF
sudo make install
```

## 🧠 C++ 实现代码（main.cpp）

```cpp
#include <crow.h>
#include <crow/websocket.h>
#include <string>
#include <vector>
#include <mutex>
#include <algorithm>
#include <memory>

// HTML 转义防止 XSS
std::string escape_html(const std::string& input) {
    std::string output;
    output.reserve(input.size() * 1.2);
    for (char c : input) {
        switch (c) {
            case '&':  output += "&amp;";  break;
            case '<':  output += "&lt;";   break;
            case '>':  output += "&gt;";   break;
            case '"':  output += "&quot;"; break;
            case '\'': output += "&#39;";  break;
            default:   output += c;        break;
        }
    }
    return output;
}

// 帖子结构
struct Post {
    std::string content;
    std::string html;
};

// 全局状态
std::vector<Post> posts;
std::mutex posts_mutex;
std::vector<std::shared_ptr<crow::websocket::connection>> ws_connections;
std::mutex ws_mutex;

// 生成帖子 HTML
std::string generate_post_html(const std::string& content) {
    return "<div class=\"post\"><p>" + escape_html(content) + "</p></div>";
}

// 广播新帖子
void broadcast_post(const std::string& html) {
    std::lock_guard<std::mutex> lock(ws_mutex);
    std::string message = "{\"html\": \"" + html + "\"}";
    for (auto& conn : ws_connections) {
        try {
            conn->send_text(message);
        } catch (...) {
            // 忽略发送失败的连接
        }
    }
}

int main() {
    crow::SimpleApp app;

    // 主页
    CROW_ROUTE(app, "/")
    ([]() {
        std::string html = R"(
        <!DOCTYPE html>
        <html>
        <head>
            <title>社交媒体平台</title>
            <script src="https://cdn.jsdelivr.net/npm/@microsoft/signalr@7/dist/browser/signalr.min.js"></script>
        </head>
        <body>
            <h1>发布新动态</h1>
            <form id="postForm">
                <textarea id="content" name="content" rows="4" cols="50" maxlength="500"></textarea><br>
                <button type="submit">发布</button>
            </form>
            <div id="posts"></div>
            <script>
                const ws = new WebSocket("ws://localhost:8080/ws");
                ws.onmessage = function(event) {
                    const data = JSON.parse(event.data);
                    const postsDiv = document.getElementById("posts");
                    postsDiv.innerHTML += data.html;
                };
                document.getElementById("postForm").onsubmit = function(e) {
                    e.preventDefault();
                    const content = document.getElementById("content").value;
                    fetch("/submit", {
                        method: "POST",
                        headers: {"Content-Type": "application/x-www-form-urlencoded"},
                        body: "content=" + encodeURIComponent(content)
                    });
                    document.getElementById("content").value = "";
                };
            </script>
        </body>
        </html>)";
        return html;
    });

    // 提交帖子
    CROW_ROUTE(app, "/submit")
    .methods("POST"_method)
    ([](const crow::request& req) {
        auto params = crow::curl::multiform(req.body);
        auto it = params.find("content");
        if (it == params.end() || it->second.empty()) {
            return crow::response(400, "Invalid content");
        }

        std::string content = it->second;
        if (content.length() > 500) {
            return crow::response(400, "Content too long");
        }

        std::string html = generate_post_html(content);

        {
            std::lock_guard<std::mutex> lock(posts_mutex);
            posts.push_back({content, html});
        }

        broadcast_post(html);
        return crow::response(200, "Post submitted");
    });

    // WebSocket 路由
    CROW_WEBSOCKET_ROUTE(app, "/ws")
    .onaccept([&](const crow::request&, void**) { return true; })
    .onopen([&](crow::websocket::connection& conn) {
        std::lock_guard<std::mutex> lock(ws_mutex);
        ws_connections.push_back(conn.shared_from_this());

        // 发送历史帖子
        std::lock_guard<std::mutex> plock(posts_mutex);
        for (const auto& post : posts) {
            std::string msg = "{\"html\": \"" + post.html + "\"}";
            conn.send_text(msg);
        }
    })
    .onclose([&](crow::websocket::connection& conn, const std::string&, uint16_t) {
        std::lock_guard<std::mutex> lock(ws_mutex);
        ws_connections.erase(
            std::remove_if(ws_connections.begin(), ws_connections.end(),
                [&conn](const std::shared_ptr<crow::websocket::connection>& c) {
                    return c.get() == &conn;
                }),
            ws_connections.end()
        );
    });

    app.port(8080).multithreaded().run();
    return 0;
}
```

