# ⚠️ 严重安全漏洞警告

您的代码存在**格式化字符串漏洞**，攻击者可通过 `%n`、`%x` 等说明符读取/写入内存，导致信息泄露或代码执行。

## 修复后的代码 + 单元测试

```cpp
// question.h
#ifndef QUESTION_H
#define QUESTION_H

#include <string>
#include <iostream>

class Question {
public:
    // 修复：使用 %s 占位符，不直接将用户输入作为格式化字符串
    void displayQuestion(const std::string& question) {
        printf("%s", question.c_str());  // 安全写法
        // 或更推荐：std::cout << question;
    }

    std::string getDisplayOutput(const std::string& question) {
        return question;  // 用于测试的纯函数
    }
};

#endif
```

```cpp
// question_test.cpp
#include <iostream>
#include <cassert>
#include <string>
#include "question.h"

class TestQuestion {
public:
    static void testNormalQuestion() {
        Question q;
        std::string input = "What is the answer?";
        std::string output = q.getDisplayOutput(input);
        assert(output == input);
        std::cout << "✓ testNormalQuestion passed\n";
    }

    static void testFormatStringAttack() {
        Question q;
        // 攻击载荷：尝试利用格式化字符串漏洞
        std::string attackInput = "What is the answer? %n %x %x %x";
        std::string output = q.getDisplayOutput(attackInput);
        // 修复后应该原样输出，不解释格式化符号
        assert(output == attackInput);
        std::cout << "✓ testFormatStringAttack passed\n";
    }

    static void testSpecialCharacters() {
        Question q;
        std::string input = "Test %s %d %%n %%x special chars";
        std::string output = q.getDisplayOutput(input);
        assert(output == input);
        std::cout << "✓ testSpecialCharacters passed\n";
    }

    static void testEmptyString() {
        Question q;
        std::string input = "";
        std::string output = q.getDisplayOutput(input);
        assert(output == input);
        std::cout << "✓ testEmptyString passed\n";
    }

    static void runAllTests() {
        std::cout << "=== Running Security Tests ===\n";
        testNormalQuestion();
        testFormatStringAttack();
        testSpecialCharacters();
        testEmptyString();
        std::cout << "=== All tests passed! ===\n";
    }
};

int main() {
    TestQuestion::runAllTests();
    return 0;
}
