## 核心设计思路

### 关键问题与解决方案

| 问题 | 解决方案 |
|------|----------|
| 浮点数精度丢失 | 使用 `round()` + 小量 epsilon 修正 |
| 溢出风险 | 使用 `int64_t` 并验证范围 |
| 负数处理 | 支持负数，保持符号一致性 |
| 输入验证 | 检查 NaN、Inf、范围等 |

## 完整代码实现

```cpp
#include <iostream>
#include <cmath>
#include <limits>
#include <stdexcept>
#include <cstdint>
#include <string>
#include <iomanip>

/**
 * @brief 金融交易金额转换工具类
 * 
 * 将浮点数金额转换为整数最小货币单位（如美分）
 * 支持美元->美分转换（1美元 = 100美分）
 */
class CurrencyConverter {
private:
    // 货币单位换算因子（美元到美分）
    static constexpr int64_t CURRENCY_FACTOR = 100;

    // 浮点数比较的epsilon值
    static constexpr double EPSILON = 1e-9;

    // 最大允许金额（防止溢出）
    static constexpr double MAX_AMOUNT = 922337203685477.58; // int64_t最大值/100

    // 最小允许金额
    static constexpr double MIN_AMOUNT = -922337203685477.58;

public:
    /**
     * @brief 转换结果状态码
     */
    enum class ConvertStatus {
        SUCCESS = 0,
        ERROR_NAN,              // 输入为NaN
        ERROR_INFINITY,         // 输入为无穷大
        ERROR_OUT_OF_RANGE,     // 超出可表示范围
        ERROR_PRECISION_LOSS    // 精度损失警告
    };

    /**
     * @brief 转换结果结构体
     */
    struct ConvertResult {
        int64_t cents;              // 转换后的美分值
        ConvertStatus status;       // 状态码
        std::string message;        // 详细信息

        bool isSuccess() const {
            return status == ConvertStatus::SUCCESS;
        }
    };

    /**
     * @brief 将美元金额转换为美分（主转换函数）
     * 
     * @param dollars 美元金额（浮点数）
     * @return ConvertResult 转换结果
     * 
     * @note 使用 round() 确保正确的四舍五入
     * @note 添加 epsilon 处理浮点数精度问题
     */
    static ConvertResult dollarsToCents(double dollars) {
        ConvertResult result;

        // 1. 验证 NaN
        if (std::isnan(dollars)) {
            result.status = ConvertStatus::ERROR_NAN;
            result.message = "输入金额为 NaN";
            result.cents = 0;
            return result;
        }

        // 2. 验证无穷大
        if (std::isinf(dollars)) {
            result.status = ConvertStatus::ERROR_INFINITY;
            result.message = "输入金额为无穷大";
            result.cents = 0;
            return result;
        }

        // 3. 验证范围
        if (dollars > MAX_AMOUNT || dollars < MIN_AMOUNT) {
            result.status = ConvertStatus::ERROR_OUT_OF_RANGE;
            result.message = "金额超出可表示范围";
            result.cents = 0;
            return result;
        }

        // 4. 核心转换：使用 round() + epsilon 处理精度
        // 添加 epsilon 避免 0.005 等边界情况的精度问题
        double adjusted = dollars + (dollars >= 0 ? EPSILON : -EPSILON);
        result.cents = static_cast<int64_t>(std::round(adjusted * CURRENCY_FACTOR));

        // 5. 验证转换后是否溢出
        if (result.cents > std::numeric_limits<int64_t>::max() / CURRENCY_FACTOR ||
            result.cents < std::numeric_limits<int64_t>::min() / CURRENCY_FACTOR) {
            result.status = ConvertStatus::ERROR_OUT_OF_RANGE;
            result.message = "转换后结果溢出";
            result.cents = 0;
            return result;
        }

        // 6. 验证精度损失（可选警告）
        double reverseCheck = static_cast<double>(result.cents) / CURRENCY_FACTOR;
        if (std::abs(reverseCheck - dollars) > EPSILON * 10) {
            result.status = ConvertStatus::ERROR_PRECISION_LOSS;
            result.message = "警告：存在精度损失";
            // 仍然返回成功，但标记警告
        } else {
            result.status = ConvertStatus::SUCCESS;
            result.message = "转换成功";
        }

        return result;
    }

    /**
     * @brief 将美分转换回美元（反向转换）
     * 
     * @param cents 美分金额
     * @return double 美元金额
     */
    static double centsToDollars(int64_t cents) {
        return static_cast<double>(cents) / CURRENCY_FACTOR;
    }

    /**
     * @brief 格式化输出金额（用于显示）
     * 
     * @param cents 美分金额
     * @param currencySymbol 货币符号
     * @return std::string 格式化后的金额字符串
     */
    static std::string formatCurrency(int64_t cents, const std::string& currencySymbol = "$") {
        double dollars = centsToDollars(cents);
        std::ostringstream oss;
        oss << currencySymbol << std::fixed << std::setprecision(2) << std::abs(dollars);

        if (cents < 0) {
            return "-" + oss.str();
        }
        return oss.str();
    }

    /**
     * @brief 获取状态码描述
     */
    static std::string getStatusMessage(ConvertStatus status) {
        switch (status) {
            case ConvertStatus::SUCCESS: return "成功";
            case ConvertStatus::ERROR_NAN: return "错误：NaN";
            case ConvertStatus::ERROR_INFINITY: return "错误：无穷大";
            case ConvertStatus::ERROR_OUT_OF_RANGE: return "错误：超出范围";
            case ConvertStatus::ERROR_PRECISION_LOSS: return "警告：精度损失";
            default: return "未知状态";
        }
    }
};

