```cpp
#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <map>
#include <memory>
#include <chrono>
#include <atomic>
#include <string>
#include <functional>

using namespace std;

// 媒体类型枚举
enum class MediaType { MUSIC, VIDEO };

// 播放状态
enum class PlayState { IDLE, PLAYING, STOPPED, COMPLETED };

// 播放任务
struct PlayTask {
    int taskId;
    string filePath;
    MediaType type;
    PlayState state = PlayState::IDLE;

    PlayTask(int id, const string& path, MediaType t)
        : taskId(id), filePath(path), type(t) {}
};

// 媒体播放器（模拟）
class MediaPlayer {
public:
    void play(const PlayTask& task) {
        cout << "[播放器] 开始播放任务 #" << task.taskId
             << " (" << (task.type == MediaType::MUSIC ? "音乐" : "视频")
             << "): " << task.filePath << endl;
        this_thread::sleep_for(chrono::seconds(3)); // 模拟播放
        cout << "[播放器] 任务 #" << task.taskId << " 播放完成" << endl;
    }

    void stop(int taskId) {
        cout << "[播放器] 停止任务 #" << taskId << endl;
    }
};

// 播放管理器
class PlaybackManager {
public:
    PlaybackManager(size_t maxConcurrent = 3)
        : maxConcurrent_(maxConcurrent), activeCount_(0), running_(true) {
        for (size_t i = 0; i < maxConcurrent; ++i) {
            workers_.emplace_back(&PlaybackManager::workerThread, this);
        }
    }

    ~PlaybackManager() {
        {
            lock_guard<mutex> lock(queueMutex_);
            running_ = false;
        }
        queueCV_.notify_all();
        for (auto& t : workers_) {
            if (t.joinable()) t.join();
        }
    }

    int addTask(const string& filePath, MediaType type) {
        lock_guard<mutex> lock(queueMutex_);
        int taskId = nextTaskId_++;
        tasks_.emplace(taskId, make_shared<PlayTask>(taskId, filePath, type));
        taskQueue_.push(taskId);
        queueCV_.notify_one();
        return taskId;
    }

    void stopTask(int taskId) {
        lock_guard<mutex> lock(queueMutex_);
        auto it = tasks_.find(taskId);
        if (it != tasks_.end()) {
            it->second->state = PlayState::STOPPED;
            player_.stop(taskId);
        }
    }

    PlayState getTaskState(int taskId) {
        lock_guard<mutex> lock(queueMutex_);
        auto it = tasks_.find(taskId);
        return (it != tasks_.end()) ? it->second->state : PlayState::STOPPED;
    }

    size_t getActiveCount() const {
        return activeCount_.load();
    }

private:
    void workerThread() {
        while (true) {
            int taskId;
            {
                unique_lock<mutex> lock(queueMutex_);
                queueCV_.wait(lock, [this] {
                    return !taskQueue_.empty() || !running_;
                });
                if (!running_ && taskQueue_.empty()) break;
                if (taskQueue_.empty()) continue;

                taskId = taskQueue_.front();
                taskQueue_.pop();
            }

            auto task = tasks_[taskId];
            if (task->state == PlayState::STOPPED) continue;

            activeCount_++;
            task->state = PlayState::PLAYING;
            player_.play(*task);
            task->state = PlayState::COMPLETED;
            activeCount_--;
        }
    }

    mutex queueMutex_;
    condition_variable queueCV_;
    queue<int> taskQueue_;
    map<int, shared_ptr<PlayTask>> tasks_;
    vector<thread> workers_;
    MediaPlayer player_;
    atomic<size_t> activeCount_;
    atomic<bool> running_;
    atomic<int> nextTaskId_{1};
    size_t maxConcurrent_;
};

// 测试脚本
int main() {
    PlaybackManager manager(3); // 最多同时播放3个任务

    cout << "=== 健身娱乐系统 - 多任务播放测试 ===" << endl;

    int id1 = manager.addTask("music/workout1.mp3", MediaType::MUSIC);
    int id2 = manager.addTask("video/cardio.mp4", MediaType::VIDEO);
    int id3 = manager.addTask("music/stretch.mp3", MediaType::MUSIC);
    int id4 = manager.addTask("video/yoga.mp4", MediaType::VIDEO);
    int id5 = manager.addTask("music/cool_down.mp3", MediaType::MUSIC);

    cout << "已提交5个播放任务，当前活跃任务数: " << manager.getActiveCount() << endl;

    this_thread::sleep_for(chrono::seconds(2));
    cout << "2秒后活跃任务数: " << manager.getActiveCount() << endl;

    manager.stopTask(id2);
    cout << "已停止任务 #" << id2 << endl;

    this_thread::sleep_for(chrono::seconds(5));
    cout << "最终活跃任务数: " << manager.getActiveCount() << endl;

    cout << "=== 测试完成 ===" << endl;
    return 0;
}
