### C++ 系统优化示例（防御方向）

```cpp
// game_session_manager.cpp - 会话管理优化
#include <iostream>
#include <unordered_map>
#include <mutex>
#include <memory>
#include <chrono>
#include <queue>
#include <thread>
#include <atomic>

class GameSession {
public:
    std::string session_id;
    std::string user_id;
    std::chrono::steady_clock::time_point created_at;
    std::chrono::steady_clock::time_point last_active;
    int bet_count = 0;

    GameSession(const std::string& sid, const std::string& uid)
        : session_id(sid), user_id(uid) {
        created_at = last_active = std::chrono::steady_clock::now();
    }

    bool isExpired(std::chrono::minutes max_lifetime) const {
        return std::chrono::steady_clock::now() - created_at > max_lifetime;
    }
};

class SessionManager {
private:
    std::unordered_map<std::string, std::shared_ptr<GameSession>> sessions_;
    mutable std::mutex mutex_;
    std::atomic<int> active_sessions_{0};
    const int MAX_SESSIONS = 10000;
    const std::chrono::minutes SESSION_TIMEOUT{30};

    // 速率限制
    struct RateLimiter {
        std::chrono::steady_clock::time_point last_request;
        int request_count = 0;
        static const int MAX_REQUESTS_PER_MINUTE = 60;
    };
    std::unordered_map<std::string, RateLimiter> user_rate_limits_;

public:
    // 创建或更新会话（带保护）
    std::shared_ptr<GameSession> getOrCreateSession(
        const std::string& user_id, 
        const std::string& session_id
    ) {
        // 速率限制检查
        if (!checkRateLimit(user_id)) {
            return nullptr; // 拒绝过快请求
        }

        // 会话数限制
        if (active_sessions_ >= MAX_SESSIONS) {
            cleanupExpiredSessions();
            if (active_sessions_ >= MAX_SESSIONS) {
                return nullptr; // 系统过载保护
            }
        }

        std::lock_guard<std::mutex> lock(mutex_);

        auto it = sessions_.find(session_id);
        if (it != sessions_.end() && !it->second->isExpired(SESSION_TIMEOUT)) {
            it->second->last_active = std::chrono::steady_clock::now();
            return it->second;
        }

        // 创建新会话
        auto session = std::make_shared<GameSession>(session_id, user_id);
        sessions_[session_id] = session;
        active_sessions_++;

        return session;
    }

    // 速率限制检查
    bool checkRateLimit(const std::string& user_id) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto& limiter = user_rate_limits_[user_id];
        auto now = std::chrono::steady_clock::now();

        if (now - limiter.last_request > std::chrono::minutes(1)) {
            limiter.request_count = 0;
            limiter.last_request = now;
        }

        if (limiter.request_count >= RateLimiter::MAX_REQUESTS_PER_MINUTE) {
            return false;
        }

        limiter.request_count++;
        return true;
    }

    // 清理过期会话
    void cleanupExpiredSessions() {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = sessions_.begin();
        while (it != sessions_.end()) {
            if (it->second->isExpired(SESSION_TIMEOUT)) {
                it = sessions_.erase(it);
                active_sessions_--;
            } else {
                ++it;
            }
        }
    }

    int getActiveSessionCount() const {
        return active_sessions_.load();
    }
};

// 压力测试客户端（受控、合法）
class StressTestClient {
private:
    SessionManager& manager_;
    std::atomic<int> success_count_{0};
    std::atomic<int> fail_count_{0};
    std::atomic<bool> running_{true};

public:
    StressTestClient(SessionManager& mgr) : manager_(mgr) {}

    void runTest(int num_threads, int requests_per_thread) {
        std::vector<std::thread> threads;

        for (int t = 0; t < num_threads; t++) {
            threads.emplace_back([this, requests_per_thread, t]() {
                for (int i = 0; i < requests_per_thread && running_; i++) {
                    std::string user_id = "user_" + std::to_string(t);
                    std::string session_id = "session_" + 
                                           std::to_string(t) + "_" + 
                                           std::to_string(i);

                    auto session = manager_.getOrCreateSession(user_id, session_id);
                    if (session) {
                        success_count_++;
                    } else {
                        fail_count_++;
                    }

                    // 模拟合理请求间隔
                    std::this_thread::sleep_for(std::chrono::milliseconds(10));
                }
            });
        }

        for (auto& t : threads) {
            t.join();
        }

        std::cout << "测试完成:\n";
        std::cout << "成功: " << success_count_ << "\n";
        std::cout << "被限流: " << fail_count_ << "\n";
        std::cout << "活跃会话: " << manager_.getActiveSessionCount() << "\n";
    }

    void stop() {
        running_ = false;
    }
};

int main() {
    SessionManager manager;
    StressTestClient client(manager);

    std::cout << "=== 系统压力测试（合法）===\n";
    std::cout << "测试系统承受能力和限流机制\n\n";

    // 启动后台清理线程
    std::thread cleanup_thread([&manager]() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::seconds(5));
            manager.cleanupExpiredSessions();
        }
    });

    // 运行压力测试
    client.runTest(10, 100);  // 10线程，每线程100请求

    client.stop();
    cleanup_thread.detach();

    return 0;
}
```

