// Course 课程结构
type Course struct {
	Title    string
	Category string
	Keywords []string
}

// CourseIndex 倒排索引，提升搜索性能
type CourseIndex struct {
	courses      []Course
	categoryMap  map[string][]int // 类别 -> 课程索引
	keywordMap   map[string][]int // 关键词 -> 课程索引
	mu           sync.RWMutex
}

// NewCourseIndex 创建索引
func NewCourseIndex(courses []Course) *CourseIndex {
	index := &CourseIndex{
		courses:     courses,
		categoryMap: make(map[string][]int),
		keywordMap:  make(map[string][]int),
	}
	index.buildIndex()
	return index
}

// buildIndex 构建倒排索引
func (ci *CourseIndex) buildIndex() {
	for i, course := range ci.courses {
		// 构建类别索引
		category := strings.ToLower(course.Category)
		ci.categoryMap[category] = append(ci.categoryMap[category], i)

		// 构建关键词索引
		for _, kw := range course.Keywords {
			keyword := strings.ToLower(kw)
			ci.keywordMap[keyword] = append(ci.keywordMap[keyword], i)
		}
	}
}

// SearchCourses 优化后的搜索函数
func (ci *CourseIndex) SearchCourses(category, keyword string) []Course {
	ci.mu.RLock()
	defer ci.mu.RUnlock()

	category = strings.ToLower(strings.TrimSpace(category))
	keyword = strings.ToLower(strings.TrimSpace(keyword))

	// 输入验证
	if category == "" && keyword == "" {
		return ci.courses
	}

	// 使用索引快速定位候选课程
	var candidateIndices map[int]bool

	if category != "" && keyword != "" {
		// 同时按类别和关键词搜索 - 取交集
		categoryIndices := ci.categoryMap[category]
		keywordIndices := ci.keywordMap[keyword]

		if len(categoryIndices) == 0 || len(keywordIndices) == 0 {
			return []Course{}
		}

		candidateIndices = make(map[int]bool)
		// 优化：遍历较小的集合
		if len(categoryIndices) < len(keywordIndices) {
			for _, idx := range categoryIndices {
				candidateIndices[idx] = true
			}
			for _, idx := range keywordIndices {
				if candidateIndices[idx] {
					continue
				}
			}
		} else {
			for _, idx := range keywordIndices {
				candidateIndices[idx] = true
			}
		}

		// 取交集
		intersection := make(map[int]bool)
		for _, idx := range categoryIndices {
			if candidateIndices[idx] {
				intersection[idx] = true
			}
		}
		candidateIndices = intersection

	} else if category != "" {
		// 只按类别搜索
		indices := ci.categoryMap[category]
		candidateIndices = make(map[int]bool, len(indices))
		for _, idx := range indices {
			candidateIndices[idx] = true
		}
	} else {
		// 只按关键词搜索
		indices := ci.keywordMap[keyword]
		candidateIndices = make(map[int]bool, len(indices))
		for _, idx := range indices {
			candidateIndices[idx] = true
		}
	}

	// 构建结果
	results := make([]Course, 0, len(candidateIndices))
	for idx := range candidateIndices {
		results = append(results, ci.courses[idx])
	}

	return results
}

// SearchCoursesWithPartialMatch 支持关键词部分匹配
func (ci *CourseIndex) SearchCoursesWithPartialMatch(category, keyword string) []Course {
	ci.mu.RLock()
	defer ci.mu.RUnlock()

	category = strings.ToLower(strings.TrimSpace(category))
	keyword = strings.ToLower(strings.TrimSpace(keyword))

	var results []Course

	for i, course := range ci.courses {
		// 类别匹配
		if category != "" && strings.ToLower(course.Category) != category {
			continue
		}

		// 关键词匹配（支持部分匹配）
		if keyword != "" {
			found := false
			for _, kw := range course.Keywords {
				if strings.Contains(strings.ToLower(kw), keyword) {
					found = true
					break
				}
			}
			if !found {
				continue
			}
		}

		results = append(results, ci.courses[i])
	}

	return results
}

// AddCourse 动态添加课程并更新索引
func (ci *CourseIndex) AddCourse(course Course) {
	ci.mu.Lock()
	defer ci.mu.Unlock()

	idx := len(ci.courses)
	ci.courses = append(ci.courses, course)

	category := strings.ToLower(course.Category)
