# 优化后的二手车交易平台 API 代码

```go
package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"strings"
	"syscall"
	"time"
)

// Car 车辆结构体
type Car struct {
	ID    string `json:"id"`
	Brand string `json:"brand"`
	Model string `json:"model"`
	Price int    `json:"price"`
}

// APIResponse 统一API响应格式
type APIResponse struct {
	Success bool        `json:"success"`
	Data    interface{} `json:"data,omitempty"`
	Error   string      `json:"error,omitempty"`
}

// Server 服务器结构
type Server struct {
	cars   []Car
	router *http.ServeMux
}

// NewServer 创建新服务器
func NewServer() *Server {
	return &Server{
		cars: []Car{
			{"1", "Toyota", "Camry", 15000},
			{"2", "Honda", "Civic", 12000},
			{"3", "Ford", "Focus", 11000},
			{"4", "Toyota", "Corolla", 13000},
			{"5", "Honda", "Accord", 18000},
		},
		router: http.NewServeMux(),
	}
}

// 中间件：日志记录
func loggingMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		next(w, r)
		log.Printf("%s %s %s", r.Method, r.URL.Path, time.Since(start))
	}
}

// 中间件：CORS
func corsMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
		w.Header().Set("Access-Control-Allow-Headers", "Content-Type")

		if r.Method == "OPTIONS" {
			w.WriteHeader(http.StatusOK)
			return
		}
		next(w, r)
	}
}

// 统一响应函数
func respondJSON(w http.ResponseWriter, status int, data interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)

	response := APIResponse{
		Success: status >= 200 && status < 300,
		Data:    data,
	}

	if err := json.NewEncoder(w).Encode(response); err != nil {
		log.Printf("Error encoding response: %v", err)
	}
}

// 错误响应
func respondError(w http.ResponseWriter, status int, message string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)

	response := APIResponse{
		Success: false,
		Error:   message,
	}

	json.NewEncoder(w).Encode(response)
}

// 获取所有车辆（支持过滤）
func (s *Server) getCars(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		respondError(w, http.StatusMethodNotAllowed, "Method not allowed")
		return
	}

	// 查询参数过滤
	query := r.URL.Query()
	brand := query.Get("brand")
	maxPrice := query.Get("max_price")
	minPrice := query.Get("min_price")

	filteredCars := make([]Car, 0)

	for _, car := range s.cars {
		// 品牌过滤
		if brand != "" && !strings.EqualFold(car.Brand, brand) {
			continue
		}

		// 价格过滤
		if maxPrice != "" {
			if max, err := strconv.Atoi(maxPrice); err == nil && car.Price > max {
				continue
			}
		}

		if minPrice != "" {
			if min, err := strconv.Atoi(minPrice); err == nil && car.Price < min {
				continue
			}
		}

		filteredCars = append(filteredCars, car)
	}

	respondJSON(w, http.StatusOK, filteredCars)
}

// 获取单个车辆
func (s *Server) getCarByID(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		respondError(w, http.StatusMethodNotAllowed, "Method not allowed")
		return
	}

	// 从URL路径获取ID
	parts := strings.Split(r.URL.Path, "/")
	if len(parts) < 4 {
		respondError(w, http.StatusBadRequest, "Invalid car ID")
		return
	}

	carID := parts[3]

	for _, car := range s.cars {
		if car.ID == carID {
			respondJSON(w, http.StatusOK, car)
			return
		}
	}

	respondError(w, http.StatusNotFound, "Car not found")
}

// 健康检查
func healthCheck(w http.ResponseWriter, r *http.Request) {
	respondJSON(w, http.StatusOK, map[string]string{
		"status": "healthy",
		"time":   time.Now().Format(time.RFC3339),
	})
}

// 注册路由
func (s *Server) registerRoutes() {
	s.router.HandleFunc("/api/cars", loggingMiddleware(corsMiddleware(s.getCars)))
	s.router.HandleFunc("/api/cars/", loggingMiddleware(corsMiddleware(s.getCarByID)))
	s.router.HandleFunc("/health", loggingMiddleware(healthCheck))
}

// 启动服务器
func (s *Server) Start(port string) error {
	s.registerRoutes()

	server := &http.Server{
		Addr:         ":" + port,
		Handler:      s.router,
		ReadTimeout:  15 * time.Second,
		WriteTimeout: 15 * time.Second,
		IdleTimeout:  60 * time.Second,
	}

	// 优雅关闭
	go func() {
		sigChan := make(chan os.Signal, 1)
		signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)
		<-sigChan

		log.Println("Shutting down server...")
		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		defer cancel()

		if err := server.Shutdown(ctx); err != nil {
			log.Printf("Server shutdown error: %v", err)
		}
	}()

	log.Printf("Server starting on port %s", port)
	if err := server.ListenAndServe(); err != http.ErrServerClosed {
		return fmt.Errorf("server error: %w", err)
	}

	return nil
}

func main() {
	// 从环境变量获取端口，默认8080
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	server := NewServer()

	if err := server.Start(port); err != nil {
		log.Fatalf("Failed to start server: %v", err)
	}
}
