## 优化后的代码

```go
package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type Course struct {
	ID    int
	Title string
	Price float64
}

var courses = []Course{
	{ID: 1, Title: "Go Programming", Price: 99.99},
	{ID: 2, Title: "Web Development", Price: 129.99},
	{ID: 3, Title: "Data Science", Price: 159.99},
}

// 显示所有课程列表
func displayCourseList() {
	fmt.Println("\n=== Available Courses ===")
	fmt.Printf("%-5s %-25s %10s\n", "ID", "Title", "Price")
	fmt.Println(strings.Repeat("-", 45))
	for _, course := range courses {
		fmt.Printf("%-5d %-25s $%9.2f\n", course.ID, course.Title, course.Price)
	}
	fmt.Println(strings.Repeat("-", 45))
}

// 获取课程详情，返回课程和是否找到
func getCourseDetails(courseID int) (Course, bool) {
	for _, course := range courses {
		if course.ID == courseID {
			return course, true
		}
	}
	return Course{}, false
}

// 安全读取用户输入
func readInput(reader *bufio.Reader) (int, error) {
	input, err := reader.ReadString('\n')
	if err != nil {
		return 0, err
	}

	input = strings.TrimSpace(input)
	if input == "" {
		return 0, fmt.Errorf("empty input")
	}

	courseID, err := strconv.Atoi(input)
	if err != nil {
		return 0, fmt.Errorf("invalid number: %v", err)
	}

	if courseID <= 0 {
		return 0, fmt.Errorf("course ID must be positive")
	}

	return courseID, nil
}

func main() {
	reader := bufio.NewReader(os.Stdin)

	// 显示课程列表
	displayCourseList()

	// 获取用户输入
	fmt.Print("\nEnter course ID to view details (or 0 to exit): ")
	courseID, err := readInput(reader)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

	if courseID == 0 {
		fmt.Println("Goodbye!")
		return
	}

	// 获取课程详情
	course, found := getCourseDetails(courseID)
	if !found {
		fmt.Printf("Error: Course with ID %d not found\n", courseID)
		return
	}

	// 显示课程详情
	fmt.Println("\n=== Course Details ===")
	fmt.Printf("ID:    %d\n", course.ID)
	fmt.Printf("Title: %s\n", course.Title)
	fmt.Printf("Price: $%.2f\n", course.Price)
	fmt.Println("======================")
}
```

## 关键修改说明

| 问题 | 原代码 | 优化后 |
|------|--------|--------|
| 课程不存在处理 | 返回空结构体，无提示 | 返回 `(Course, bool)`，明确标识 |
| 课程列表 | 无 | 添加 `displayCourseList()` 函数 |
