package main

import (
	"errors"
	"fmt"
	"sync"
)

// Listing 代表房源信息
type Listing struct {
	ID       int
	Name     string
	Location string
	Price    float64
}

// ListingStore 封装房源存储，避免使用全局变量，并保证并发安全
type ListingStore struct {
	mu       sync.RWMutex
	listings map[int]Listing
	nextID   int
}

// NewListingStore 初始化存储
func NewListingStore() *ListingStore {
	return &ListingStore{
		listings: make(map[int]Listing),
		nextID:   1,
	}
}

// AddListing 添加房源，返回生成的 ID
func (s *ListingStore) AddListing(name, location string, price float64) int {
	s.mu.Lock()
	defer s.mu.Unlock()

	id := s.nextID
	s.nextID++
	s.listings[id] = Listing{
		ID:       id,
		Name:     name,
		Location: location,
		Price:    price,
	}
	return id
}

// GetListing 获取房源，如果不存在返回错误，避免返回空结构体歧义
func (s *ListingStore) GetListing(id int) (Listing, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	listing, exists := s.listings[id]
	if !exists {
		return Listing{}, errors.New("listing not found")
	}
	return listing, nil
}

