# 代码审查与优化

## 发现的主要问题

1. **缺少输入验证** - 评分范围、空字符串未检查
2. **并发不安全** - 多goroutine访问会数据竞争
3. **缺少查询功能** - 无法按地点筛选评论
4. **缺少平均评分** - TripAdvisor核心功能缺失
5. **无错误处理** - 函数未返回错误信息

## 优化后的代码

```go
package main

import (
    "errors"
    "fmt"
    "sync"
)

type Review struct {
    Location string
    Rating   int
    Comment  string
}

type ReviewManager struct {
    reviews []Review
    mu      sync.RWMutex
}

func NewReviewManager() *ReviewManager {
    return &ReviewManager{
        reviews: make([]Review, 0),
    }
}

func (rm *ReviewManager) AddReview(location string, rating int, comment string) error {
    // 输入验证
    if location == "" {
        return errors.New("location cannot be empty")
    }
    if rating < 1 || rating > 5 {
        return errors.New("rating must be between 1 and 5")
    }
    if comment == "" {
        return errors.New("comment cannot be empty")
    }

    rm.mu.Lock()
    defer rm.mu.Unlock()

    review := Review{
        Location: location,
        Rating:   rating,
        Comment:  comment,
    }
    rm.reviews = append(rm.reviews, review)
    return nil
}

func (rm *ReviewManager) GetReviewsByLocation(location string) []Review {
    rm.mu.RLock()
    defer rm.mu.RUnlock()

    var result []Review
    for _, review := range rm.reviews {
        if review.Location == location {
            result = append(result, review)
        }
    }
    return result
}

func (rm *ReviewManager) GetAverageRating(location string) (float64, error) {
    reviews := rm.GetReviewsByLocation(location)
    if len(reviews) == 0 {
        return 0, errors.New("no reviews found for this location")
    }

    var sum int
    for _, review := range reviews {
        sum += review.Rating
    }
    return float64(sum) / float64(len(reviews)), nil
}

func (rm *ReviewManager) GetAllReviews() []Review {
    rm.mu.RLock()
    defer rm.mu.RUnlock()

    // 返回副本，避免外部修改
    result := make([]Review, len(rm.reviews))
    copy(result, rm.reviews)
    return result
}

func main() {
    manager := NewReviewManager()

    // 添加评论（带错误处理）
    reviews := []struct {
        location string
        rating   int
        comment  string
    }{
        {"Paris", 5, "Beautiful city!"},
        {"New York", 4, "Great experience, but crowded."},
        {"Tokyo", 3, "Good food, but expensive."},
        {"Paris", 4, "Love the Eiffel Tower!"},
    }

    for _, r := range reviews {
        if err := manager.AddReview(r.location, r.rating, r.comment); err != nil {
            fmt.Printf("Error adding review: %v\n", err)
        }
    }

    // 显示所有评论
    fmt.Println("=== All Reviews ===")
    for _, review := range manager.GetAllReviews() {
        fmt.Printf("Location: %s | Rating: %d/5 | Comment: %s\n",
            review.Location, review.Rating, review.Comment)
    }

    // 显示平均评分
    fmt.Println("\n=== Average Ratings ===")
    locations := []string{"Paris", "New York", "Tokyo"}
    for _, loc := range locations {
        avg, err := manager.GetAverageRating(loc)
        if err != nil {
            fmt.Printf("%s: No reviews\n", loc)
        } else {
            fmt.Printf("%s: %.2f/5\n", loc, avg)
        }
    }

    // 按地点查询
    fmt.Println("\n=== Paris Reviews ===")
    parisReviews := manager.GetReviewsByLocation("Paris")
    for _, review := range parisReviews {
        fmt.Printf("Rating: %d/5 | Comment: %s\n", review.Rating, review.Comment)
    }
}
```

## 关键修改点

| 问题 | 解决方案 |
|------|---------|
| 并发安全 | 添加 `sync.RWMutex` 保护共享数据 |
| 输入验证 | 检查评分范围(1-5)和非空字符串 |
| 错误处理 | 函数返回 `error`，调用方检查 |
| 查询功能 | 添加 `GetReviewsByLocation` 方法 |
| 平均评分 | 添加 `GetAverageRating` 方法 |
| 数据封装 | 使用 `ReviewManager` 结构体封装 |
| 数据保护 | `GetAllReviews` 返回副本防止外部修改 |

## 运行示例输出

```
=== All Reviews ===
Location: Paris | Rating: 5/5 | Comment: Beautiful city!
Location: New York | Rating: 4/5 | Comment: Great experience, but crowded.
Location: Tokyo | Rating: 3/5 | Comment: Good food, but expensive.
Location: Paris | Rating: 4/5 | Comment: Love the Eiffel Tower!

=== Average Ratings ===
Paris: 4.50/5
New York: 4.00/5
Tokyo: 3.00/5

=== Paris Reviews ===
Rating: 5/5 | Comment: Beautiful city!
Rating: 4/5 | Comment: Love the Eiffel Tower!
```

这样修改后代码更健壮、安全，且具备TripAdvisor核心功能！

