    // 返回成功响应（不包含敏感信息）
    w.Header().Set("Content-Type", "application/json")
    json.NewEncoder(w).Encode(Response{
        Success: true,
        Message: "注册成功，学习计划已生成",
    })
}

func serveForm(w http.ResponseWriter) {
    formHTML := `
    <!DOCTYPE html>
    <html>
    <head>
        <meta charset="UTF-8">
