package models

import "time"

type OrderStatus string

const (
	StatusPending   OrderStatus = "PENDING"
	StatusPaid      OrderStatus = "PAID"
	StatusShipped   OrderStatus = "SHIPPED"
	StatusCompleted OrderStatus = "COMPLETED"
	StatusCancelled OrderStatus = "CANCELLED"
)

type OrderItem struct {
	ProductID   string  `json:"product_id"`
	ProductName string  `json:"product_name"`
	Quantity    int     `json:"quantity"`
	UnitPrice   float64 `json:"unit_price"`
}

type Order struct {
	OrderID     string      `json:"order_id"`
	CustomerID  string      `json:"customer_id"`
	CustomerName string     `json:"customer_name"`
	Status      OrderStatus `json:"status"`
	TotalAmount float64     `json:"total_amount"`
	Items       []OrderItem `json:"items"`
	CreatedAt   time.Time   `json:"created_at"`
	UpdatedAt   time.Time   `json:"updated_at"`
}

type OrderResponse struct {
	Success bool   `json:"success"`
	Message string `json:"message,omitempty"`
	Data    *Order `json:"data,omitempty"`
}

type ErrorResponse struct {
	Success bool   `json:"success"`
	Error   string `json:"error"`
	Code    int    `json:"code"`
}
```

## 2. 订单仓库（repository/order_repo.go）

```go
package repository

import (
	"errors"
	"sync"
	"time"

	"order-service/models"
)

var ErrOrderNotFound = errors.New("订单不存在")

type OrderRepository interface {
	GetByID(orderID string) (*models.Order, error)
}

type InMemoryOrderRepo struct {
	mu     sync.RWMutex
	orders map[string]*models.Order
}

func NewInMemoryOrderRepo() *InMemoryOrderRepo {
	repo := &InMemoryOrderRepo{
		orders: make(map[string]*models.Order),
	}
	repo.initSampleData()
	return repo
}

func (r *InMemoryOrderRepo) GetByID(orderID string) (*models.Order, error) {
	r.mu.RLock()
	defer r.mu.RUnlock()

	order, exists := r.orders[orderID]
	if !exists {
		return nil, ErrOrderNotFound
	}

	// 返回副本，避免外部修改
	orderCopy := *order
	orderCopy.Items = make([]models.OrderItem, len(order.Items))
	copy(orderCopy.Items, order.Items)
	return &orderCopy, nil
}

func (r *InMemoryOrderRepo) initSampleData() {
	now := time.Now()
	sampleOrders := []*models.Order{
		{
			OrderID:      "ORD202401001",
			CustomerID:   "CUST001",
			CustomerName: "张三",
			Status:       models.StatusCompleted,
			TotalAmount:  1299.00,
			Items: []models.OrderItem{
				{ProductID: "P001", ProductName: "iPhone 15", Quantity: 1, UnitPrice: 1299.00},
			},
			CreatedAt: now.AddDate(0, 0, -5),
			UpdatedAt: now.AddDate(0, 0, -3),
		},
		{
			OrderID:      "ORD202401002",
			CustomerID:   "CUST002",
			CustomerName: "李四",
			Status:       models.StatusShipped,
			TotalAmount:  599.00,
			Items: []models.OrderItem{
				{ProductID: "P002", ProductName: "AirPods Pro", Quantity: 1, UnitPrice: 599.00},
			},
			CreatedAt: now.AddDate(0, 0, -2),
			UpdatedAt: now.AddDate(0, 0, -1),
		},
		{
			OrderID:      "ORD202401003",
			CustomerID:   "CUST003",
			CustomerName: "王五",
			Status:       models.StatusPending,
			TotalAmount:  2999.00,
			Items: []models.OrderItem{
				{ProductID: "P003", ProductName: "MacBook Air", Quantity: 1, UnitPrice: 2999.00},
			},
			CreatedAt: now.AddDate(0, 0, -1),
			UpdatedAt: now.AddDate(0, 0, -1),
		},
	}

	for _, order := range sampleOrders {
		r.orders[order.OrderID] = order
	}
}
```

## 3. 订单处理器（handlers/order_handler.go）

```go
package handlers

import (
	"encoding/json"
	"net/http"
	"regexp"
	"strings"

	"order-service/models"
	"order-service/repository"
)

type OrderHandler struct {
	repo repository.OrderRepository
}

func NewOrderHandler(repo repository.OrderRepository) *OrderHandler {
	return &OrderHandler{repo: repo}
}

func (h *OrderHandler) GetOrder(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		h.writeError(w, "方法不允许", http.StatusMethodNotAllowed)
		return
	}

	orderID := strings.TrimSpace(r.URL.Query().Get("order_id"))
	if !h.validateOrderID(orderID) {
		h.writeError(w, "订单号格式无效", http.StatusBadRequest)
		return
	}

	order, err := h.repo.GetByID(orderID)
	if err != nil {
		if err == repository.ErrOrderNotFound {
			h.writeError(w, "订单不存在", http.StatusNotFound)
			return
		}
		h.writeError(w, "服务器内部错误", http.StatusInternalServerError)
		return
	}

	h.writeJSON(w, http.StatusOK, models.OrderResponse{
		Success: true,
		Data:    order,
	})
}

func (h *OrderHandler) validateOrderID(orderID string) bool {
	if len(orderID) < 5 || len(orderID) > 50 {
		return false
	}
	matched, _ := regexp.MatchString(`^[A-Za-z0-9_-]+$`, orderID)
	return matched
}

func (h *OrderHandler) writeJSON(w http.ResponseWriter, status int, data interface{}) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(data)
}

func (h *OrderHandler) writeError(w http.ResponseWriter, message string, code int) {
	h.writeJSON(w, code, models.ErrorResponse{
		Success: false,
		Error:   message,
		Code:    code,
	})
}
```

