	defer s.mu.Unlock()
	key := fmt.Sprintf("%s-%s", req.UserID, req.ClassID)
	if s.bookings[key] {
		return nil, errors.New("class already booked")
	}
	s.bookings[key] = true

	return &BookingResponse{
		Success:   true,
		Message:   "Booking confirmed",
		BookingID: fmt.Sprintf("BK-%s-%d", req.RequestID, time.Now().Unix()),
	}, nil
}

func (s *BookingService) isRetryable(err error) bool {
	return errors.Is(err, ErrNetworkTimeout) || errors.Is(err, ErrServerBusy)
}

// 模拟网络请求，含失败概率和延迟
func simulateNetworkRequest() (bool, error) {
	delay := time.Duration(500+rand.Intn(2000)) * time.Millisecond
	time.Sleep(delay)

	r := rand.Float32()
	if r < 0.3 {
		return false, ErrNetworkTimeout
	} else if r < 0.5 {
		return false, ErrServerBusy
	}
	return true, nil
}
