以下是使用 Go 语言实现的比特币钱包用户换绑功能示例代码，包含安全验证、事务处理、审计日志等关键要素，适用于生产环境参考。

```go
package wallet

import (
	"context"
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"errors"
	"fmt"
	"time"

	"github.com/google/uuid"
	"go.uber.org/zap"
)

// 错误定义
var (
	ErrInvalidOldWallet    = errors.New("旧钱包地址验证失败")
	ErrInvalidNewWallet    = errors.New("新钱包地址无效")
	ErrWalletAlreadyBound  = errors.New("新钱包已被其他用户绑定")
	ErrVerificationFailed  = errors.New("验证签名失败")
	ErrRateLimitExceeded   = errors.New("换绑请求过于频繁")
	ErrCooldownNotExpired  = errors.New("冷却期未结束，请稍后再试")
)

// WalletBindService 换绑服务
type WalletBindService struct {
	db           *sql.DB
	logger       *zap.Logger
	cooldownTime time.Duration // 换绑冷却时间
	rateLimit    int           // 单位时间最大换绑次数
}

// WalletBindRequest 换绑请求
type WalletBindRequest struct {
	UserID        string `json:"user_id"`
	OldWalletAddr string `json:"old_wallet_addr"`
	NewWalletAddr string `json:"new_wallet_addr"`
	Signature     string `json:"signature"` // 用户对换绑操作的签名
	Nonce         string `json:"nonce"`     // 防止重放攻击
}

// NewWalletBindService 创建服务实例
func NewWalletBindService(db *sql.DB, logger *zap.Logger) *WalletBindService {
	return &WalletBindService{
		db:           db,
		logger:       logger,
		cooldownTime: 7 * 24 * time.Hour, // 默认7天冷却
		rateLimit:    3,                  // 每天最多3次
	}
}

// RebindWallet 执行换绑
func (s *WalletBindService) RebindWallet(ctx context.Context, req *WalletBindRequest) error {
	// 基础验证
	if err := s.validateRequest(req); err != nil {
		return err
	}

	// 检查冷却期
	if err := s.checkCooldown(ctx, req.UserID); err != nil {
		return err
	}

	// 检查频率限制
	if err := s.checkRateLimit(ctx, req.UserID); err != nil {
		return err
	}

	// 启动事务
	tx, err := s.db.BeginTx(ctx, &sql.TxOptions{Isolation: sql.LevelSerializable})
	if err != nil {
		s.logger.Error("事务启动失败", zap.Error(err))
		return fmt.Errorf("数据库事务错误: %w", err)
	}
	defer tx.Rollback()

	// 验证旧钱包归属
	if err := s.verifyOldWallet(ctx, tx, req.UserID, req.OldWalletAddr); err != nil {
		return err
	}

	// 验证新钱包未被绑定
	if err := s.verifyNewWalletAvailable(ctx, tx, req.NewWalletAddr); err != nil {
		return err
	}

	// 验证用户签名
	if err := s.verifySignature(req); err != nil {
		return err
	}

	// 执行换绑
	if err := s.executeRebind(ctx, tx, req); err != nil {
		return err
	}

	// 记录审计日志
	if err := s.auditLog(ctx, tx, req); err != nil {
		s.logger.Warn("审计日志记录失败", zap.Error(err))
	}

	// 提交事务
	if err := tx.Commit(); err != nil {
		s.logger.Error("事务提交失败", zap.Error(err))
		return fmt.Errorf("事务提交错误: %w", err)
	}

	s.logger.Info("钱包换绑成功",
		zap.String("user_id", req.UserID),
		zap.String("new_wallet", req.NewWalletAddr))

	return nil
}

// 验证请求字段
func (s *WalletBindService) validateRequest(req *WalletBindRequest) error {
	if req.UserID == "" || req.OldWalletAddr == "" || req.NewWalletAddr == "" {
		return errors.New("缺少必要参数")
	}
	if req.OldWalletAddr == req.NewWalletAddr {
		return errors.New("新旧钱包地址不能相同")
	}
	if !isValidBitcoinAddress(req.NewWalletAddr) {
		return ErrInvalidNewWallet
	}
	return nil
}

// 检查冷却期
func (s *WalletBindService) checkCooldown(ctx context.Context, userID string) error {
	query := `SELECT last_rebind_time FROM user_wallet_bind_log 
			  WHERE user_id = $1 ORDER BY created_at DESC LIMIT 1`
	var lastTime time.Time
	err := s.db.QueryRowContext(ctx, query, userID).Scan(&lastTime)
	if err == nil && time.Since(lastTime) < s.cooldownTime {
		return ErrCooldownNotExpired
	}
	return nil
}

// 检查频率限制
func (s *WalletBindService) checkRateLimit(ctx context.Context, userID string) error {
	query := `SELECT COUNT(*) FROM user_wallet_bind_log 
			  WHERE user_id = $1 AND created_at > NOW() - INTERVAL '24 hours'`
	var count int
	if err := s.db.QueryRowContext(ctx, query, userID).Scan(&count); err != nil {
		return err
	}
	if count >= s.rateLimit {
		return ErrRateLimitExceeded
	}
	return nil
}

// 验证旧钱包归属
func (s *WalletBindService) verifyOldWallet(ctx context.Context, tx *sql.Tx, userID, walletAddr string) error {
	query := `SELECT 1 FROM user_wallets 
			  WHERE user_id = $1 AND wallet_address = $2 AND is_active = true`
	var exists int
	if err := tx.QueryRowContext(ctx, query, userID, walletAddr).Scan(&exists); err != nil {
		return ErrInvalidOldWallet
	}
	return nil
}

// 验证新钱包未被绑定
func (s *WalletBindService) verifyNewWalletAvailable(ctx context.Context, tx *sql.Tx, walletAddr string) error {
	query := `SELECT 1 FROM user_wallets WHERE wallet_address = $1 AND is_active = true`
	var exists int
	if err := tx.QueryRowContext(ctx, query, walletAddr).Scan(&exists); err == nil {
		return ErrWalletAlreadyBound
	}
	return nil
}

// 验证签名（示例逻辑，实际应使用加密库验证）
func (s *WalletBindService) verifySignature(req *WalletBindRequest) error {
	message := fmt.Sprintf("%s:%s:%s:%s", req.UserID, req.OldWalletAddr, req.NewWalletAddr, req.Nonce)
	hash := sha256.Sum256([]byte(message))
	expected := hex.EncodeToString(hash[:])
	// 实际应使用公钥验证签名，这里简化为比对哈希
	if req.Signature != expected {
		return ErrVerificationFailed
	}
	return nil
}

// 执行换绑
func (s *WalletBindService) executeRebind(ctx context.Context, tx *sql.Tx, req *WalletBindRequest) error {
	// 停用旧钱包
	_, err := tx.ExecContext(ctx,
		`UPDATE user_wallets SET is_active = false, updated_at = NOW() 
		 WHERE user_id = $1 AND wallet_address = $2`,
		req.UserID, req.OldWalletAddr)
	if err != nil {
		return err
	}

	// 绑定新钱包
	_, err = tx.ExecContext(ctx,
		`INSERT INTO user_wallets (user_id, wallet_address, is_active, created_at) 
		 VALUES ($1, $2, true, NOW())`,
		req.UserID, req.NewWalletAddr)
	return err
}

// 审计日志
func (s *WalletBindService) auditLog(ctx context.Context, tx *sql.Tx, req *WalletBindRequest) error {
	query := `INSERT INTO user_wallet_bind_log 
			  (user_id, old_wallet, new_wallet, nonce, ip_address, created_at) 
			  VALUES ($1, $2, $3, $4, $5, NOW())`
	_, err := tx.ExecContext(ctx, query, req.UserID, req.OldWalletAddr, req.NewWalletAddr, req.Nonce, "127.0.0.1")
	return err

