// 全局复用 http.Client，利用连接池提高性能，避免每次请求都创建连接
var httpClient = &http.Client{
	Timeout: 10 * time.Second, // 设置整体请求超时时间，防止 hanging
	Transport: &http.Transport{
		MaxIdleConns:        100,              // 最大空闲连接数
		IdleConnTimeout:     90 * time.Second, // 空闲连接超时
		TLSHandshakeTimeout: 10 * time.Second, // TLS 握手超时
	},
}

func fetchProductData(ctx context.Context, url string) ([]byte, error) {
	// 创建带有 Context 的请求，支持外部取消和超时控制
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return nil, fmt.Errorf("failed to create request: %w", err)
	}

	// 设置 User-Agent，避免被某些 API 网关拦截
