```go
package main

import (
	"bytes"
	"fmt"
	"io"
	"mime/multipart"
	"net/http"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

const (
	maxUploadSize = 5 * 1024 * 1024 // 5MB
	uploadDir     = "./uploads"
)

func uploadSVG(w http.ResponseWriter, r *http.Request) {
	// 限制请求体大小
	r.Body = http.MaxBytesReader(w, r.Body, maxUploadSize)

	file, header, err := r.FormFile("file")
	if err != nil {
		if strings.Contains(err.Error(), "http: request body too large") {
			http.Error(w, "File too large (max 5MB)", http.StatusRequestEntityTooLarge)
		} else {
			http.Error(w, "File upload error", http.StatusBadRequest)
		}
		return
	}
	defer file.Close()

	// 验证文件扩展名
	if !strings.HasSuffix(strings.ToLower(header.Filename), ".svg") {
		http.Error(w, "Only SVG files are allowed", http.StatusBadRequest)
		return
	}

	// 读取文件内容
	fileContent, err := io.ReadAll(file)
	if err != nil {
		http.Error(w, "Failed to read file", http.StatusInternalServerError)
		return
	}

	// 验证MIME类型
	if !bytes.HasPrefix(fileContent, []byte("<?xml")) && 
	   !bytes.HasPrefix(fileContent, []byte("<svg")) {
		http.Error(w, "Invalid SVG file format", http.StatusBadRequest)
		return
	}

	// 安全检查：防止XSS攻击
	if containsDangerousPatterns(string(fileContent)) {
		http.Error(w, "SVG file contains unsafe content", http.StatusBadRequest)
		return
	}

	// 创建上传目录
	if err := os.MkdirAll(uploadDir, 0755); err != nil {
		http.Error(w, "Server error", http.StatusInternalServerError)
		return
	}

	// 生成安全文件名
	filename := sanitizeFilename(header.Filename)
	filePath := filepath.Join(uploadDir, filename)

	// 保存文件
	if err := os.WriteFile(filePath, fileContent, 0644); err != nil {
		http.Error(w, "Failed to save file", http.StatusInternalServerError)
		return
	}

	// 返回成功响应
	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"success": true, "filename": "%s", "size": %d}`, filename, len(fileContent))
}

// 检查SVG中是否包含危险内容
func containsDangerousPatterns(content string) bool {
	dangerousPatterns := []string{
		"(?i)<script",
		"(?i)javascript:",
		"(?i)on\\w+\\s*=",
		"(?i)<iframe",
		"(?i)<object",
		"(?i)<embed",
	}

	for _, pattern := range dangerousPatterns {
		if matched, _ := regexp.MatchString(pattern, content); matched {
			return true
		}
	}
	return false
}

// 清理文件名，防止路径遍历攻击
func sanitizeFilename(filename string) string {
	filename = filepath.Base(filename)
	filename = strings.ReplaceAll(filename, "..", "")
	filename = regexp.MustCompile(`[^a-zA-Z0-9._-]`).ReplaceAllString(filename, "_")
	return filename
}

func main() {
	http.HandleFunc("/upload", uploadSVG)
	fmt.Println("Server starting on :8080")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		fmt.Printf("Server error: %v\n", err)
	}
}
```

### 关键修改点说明：

1. **文件大小限制**：使用 `http.MaxBytesReader` 限制上传文件大小为5MB，防止DoS攻击。

2. **文件类型验证**：
   - 检查文件扩展名是否为 `.svg`
   - 验证文件内容是否以 `<?xml` 或 `<svg` 开头

3. **XSS安全防护**：通过 `containsDangerousPatterns` 函数检测并阻止包含 `<script>`、`javascript:`、事件处理器等危险内容的SVG文件。

4. **文件名安全**：`sanitizeFilename` 函数防止路径遍历攻击，只允许安全字符。

5. **完整错误处理**：针对不同错误类型返回合适的HTTP状态码和错误信息。

6. **JSON响应**：返回结构化的JSON响应，便于前端处理。

7. **目录管理**：自动创建上传目录，设置合适的文件权限。

