package main

import (
	"html/template"
	"net/http"
	"sync"
	"time"
)

// Review 表示一条旅游评价
type Review struct {
	Content   string
	Timestamp time.Time
}

// ReviewStore 线程安全的评价存储
type ReviewStore struct {
	mu       sync.RWMutex
	reviews  []Review
}

var store = &ReviewStore{
	reviews: make([]Review, 0),
}

// 添加评价
func (s *ReviewStore) AddReview(content string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.reviews = append(s.reviews, Review{
		Content:   content,
		Timestamp: time.Now(),
	})
}

// 获取所有评价
func (s *ReviewStore) GetReviews() []Review {
	s.mu.RLock()
	defer s.mu.RUnlock()
	// 返回副本避免外部修改
	reviews := make([]Review, len(s.reviews))
	copy(reviews, s.reviews)
	return reviews
}

// 主页：显示表单和评价列表
func homeHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != "GET" {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	reviews := store.GetReviews()

	data := struct {
		Reviews []Review
	}{
		Reviews: reviews,
	}

