	clean := re.ReplaceAllString(input, "")
	// 限制长度
	if len(clean) > 100 {
		clean = clean[:100]
	}
	return template.HTMLEscapeString(clean)
}

// 验证价格范围
func validatePrice(priceStr string) (float64, error) {
	if priceStr == "" {
		return 0, nil
	}
	price, err := strconv.ParseFloat(priceStr, 64)
	if err != nil || price < 0 {
		return 0, err
	}
	return price, nil
}

