			continue
		}
		if minPrice > 0 && p.Price < minPrice {
			continue
		}
		if maxPrice > 0 && p.Price > maxPrice {
			continue
		}
		results = append(results, p)
	}

	// 使用模板安全渲染
	data := struct {
		SearchParams
		Results []Property
	}{
