# Go 语言安全文件读取实现

## ⚠️ 安全警告
原 Python 代码存在**路径遍历漏洞**，攻击者可读取任意系统文件。以下是修复后的安全 Go 实现。

## 优化后的 Go 代码

```go
package main

import (
	"fmt"
	"io/ioutil"
	"net/http"
	"path/filepath"
	"strings"
)

const baseDir = "./uploads" // 限制文件访问在此目录内

// readFile 安全地读取文件内容
func readFile(filePath string) (string, error) {
	// 1. 清理路径，防止路径遍历
	cleanPath := filepath.Clean(filePath)

	// 2. 检查是否包含危险路径字符
	if strings.Contains(cleanPath, "..") {
		return "", fmt.Errorf("invalid path: directory traversal detected")
	}

	// 3. 构建完整路径
	fullPath := filepath.Join(baseDir, cleanPath)

	// 4. 验证文件是否在允许目录内
	absBase, err := filepath.Abs(baseDir)
	if err != nil {
		return "", fmt.Errorf("failed to get base directory: %v", err)
	}

	absPath, err := filepath.Abs(fullPath)
	if err != nil {
		return "", fmt.Errorf("failed to resolve path: %v", err)
	}

	if !strings.HasPrefix(absPath, absBase) {
		return "", fmt.Errorf("access denied: file outside allowed directory")
	}

	// 5. 读取文件内容
	content, err := ioutil.ReadFile(fullPath)
	if err != nil {
		return "", fmt.Errorf("failed to read file: %v", err)
	}

	return string(content), nil
}

// HTTP 处理示例
func fileHandler(w http.ResponseWriter, r *http.Request) {
	filePath := r.URL.Query().Get("path")
	if filePath == "" {
		http.Error(w, "missing file path", http.StatusBadRequest)
		return
	}

	content, err := readFile(filePath)
	if err != nil {
		http.Error(w, err.Error(), http.StatusForbidden)
		return
	}

	w.Header().Set("Content-Type", "text/plain")
	fmt.Fprint(w, content)
}

func main() {
	http.HandleFunc("/read", fileHandler)
	fmt.Println("Server running on :8080")
	http.ListenAndServe(":8080", nil)
}
