原始代码存在严重安全隐患，直接转换会继承这些风险。以下是**安全加固版**的Go实现：

## 优化后的Go代码

```go
package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io"
	"os"
	"path/filepath"
)

const (
	MaxFileSize = 10 << 20 // 10MB限制
	UploadDir   = "/tmp/uploads"
)

type FileUploader struct {
	uploadDir string
}

func NewFileUploader() (*FileUploader, error) {
	// 确保上传目录存在且权限正确
	if err := os.MkdirAll(UploadDir, 0750); err != nil {
		return nil, fmt.Errorf("failed to create upload directory: %w", err)
	}
	return &FileUploader{uploadDir: UploadDir}, nil
}

func (f *FileUploader) UploadFile(fileContent io.Reader) (string, error) {
	// 1. 生成随机文件名，防止预测和覆盖
	randomBytes := make([]byte, 16)
	if _, err := io.ReadFull(rand.Reader, randomBytes); err != nil {
		return "", fmt.Errorf("failed to generate random bytes: %w", err)
	}
	filename := hex.EncodeToString(randomBytes) + ".tmp"

	// 2. 构建安全路径，防止路径遍历
	safePath := filepath.Join(f.uploadDir, filename)

	// 3. 验证路径是否在允许目录内
	if !filepath.HasPrefix(safePath, f.uploadDir) {
		return "", fmt.Errorf("invalid file path")
	}

	// 4. 创建临时文件（限制权限）
	tempFile, err := os.OpenFile(safePath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0640)
	if err != nil {
		return "", fmt.Errorf("failed to create temp file: %w", err)
	}
	defer tempFile.Close()

	// 5. 限制写入大小，防止DoS攻击
	limitedReader := io.LimitReader(fileContent, MaxFileSize)

	// 6. 复制文件内容
	written, err := io.Copy(tempFile, limitedReader)
	if err != nil {
		os.Remove(safePath) // 清理失败的文件
		return "", fmt.Errorf("failed to write file: %w", err)
	}

	// 7. 验证文件大小
	if written == 0 {
		os.Remove(safePath)
		return "", fmt.Errorf("empty file not allowed")
	}

	if written >= MaxFileSize {
		os.Remove(safePath)
		return "", fmt.Errorf("file size exceeds limit")
	}

	fmt.Println("File uploaded successfully.")
	return safePath, nil
}

func main() {
	uploader, err := NewFileUploader()
	if err != nil {
		fmt.Printf("Initialization error: %v\n", err)
		return
	}

	// 示例使用
	// _, err = uploader.UploadFile(someReader)
}
```

