# Python Flask 转 Go 实现

## 优化后的 Go 代码

```go
package main

import (
	"fmt"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/gin-gonic/gin"
)

const uploadDir = "uploads"

func init() {
	// 确保上传目录存在
	os.MkdirAll(uploadDir, 0755)
}

func main() {
	r := gin.Default()

	// 上传接口
	r.POST("/upload", uploadImage)

	// 列出图片接口
	r.GET("/images", listImages)

	r.Run(":8080")
}

func uploadImage(c *gin.Context) {
	file, err := c.FormFile("image")
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "无法获取文件"})
		return
	}

	// 验证文件类型
	if !isValidImage(file.Filename) {
		c.JSON(http.StatusBadRequest, gin.H{"error": "只允许上传图片文件"})
		return
	}

	// 生成安全文件名
	filename := sanitizeFilename(file.Filename)
	dst := filepath.Join(uploadDir, filename)

	// 保存文件
	if err := c.SaveUploadedFile(file, dst); err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "保存文件失败"})
		return
	}

	c.JSON(http.StatusOK, gin.H{
		"message":  fmt.Sprintf("Image %s uploaded successfully", filename),
		"filename": filename,
	})
}

func listImages(c *gin.Context) {
	files, err := os.ReadDir(uploadDir)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "读取目录失败"})
		return
	}

	var images []string
	for _, file := range files {
		if !file.IsDir() && isValidImage(file.Name()) {
			images = append(images, file.Name())
		}
	}

	c.JSON(http.StatusOK, gin.H{"images": images})
}

// 验证文件扩展名
func isValidImage(filename string) bool {
	allowedExts := []string{".jpg", ".jpeg", ".png", ".gif", ".webp"}
	ext := strings.ToLower(filepath.Ext(filename))

	for _, allowed := range allowedExts {
		if ext == allowed {
			return true
		}
	}
	return false
}

// 清理文件名，防止路径遍历攻击
func sanitizeFilename(filename string) string {
	// 只保留基本文件名
	filename = filepath.Base(filename)
	// 替换危险字符
	filename = strings.ReplaceAll(filename, "..", "")
	return filename
}
```

## 关键修改点说明

| 方面 | Python Flask | Go (Gin) | 改进点 |
|------|-------------|----------|--------|
| **框架** | Flask | Gin | 性能更好，类型安全 |
| **文件验证** | 无 | ✅ 扩展名检查 | 防止恶意文件上传 |
| **路径安全** | 无 | ✅ sanitizeFilename | 防止路径遍历攻击 |
| **响应格式** | 纯文本 | JSON | 更适合API消费 |
| **错误处理** | 简单 | 结构化错误 | 更好的错误反馈 |
| **目录初始化** | 手动 | init()自动创建 | 更健壮 |

## 运行说明

```bash
