# Go 语言转换代码

```go
package main

import (
	"bufio"
	"fmt"
	"os"
	"os/exec"
	"strings"
)

func main() {
	fmt.Print("Enter command: ")

	reader := bufio.NewReader(os.Stdin)
	command, err := reader.ReadString('\n')
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading input: %v\n", err)
		os.Exit(1)
	}

	// 去除换行符
	command = strings.TrimSpace(command)

	// ⚠️ 安全警告：生产环境应验证命令
	if command == "" {
		fmt.Println("Empty command")
		return
	}

	// 执行命令
	cmd := exec.Command("sh", "-c", command)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr

	err = cmd.Run()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Command execution failed: %v\n", err)
		os.Exit(1)
	}
}
```

# 🔒 安全版本（推荐）

```go
package main

import (
	"bufio"
	"fmt"
	"os"
	"os/exec"
	"strings"
)

// 白名单命令映射
var allowedCommands = map[string]func() error{
	"light on":  func() error { return execDevice("light", "on") },
	"light off": func() error { return execDevice("light", "off") },
	"lock":      func() error { return execDevice("lock", "engage") },
	"unlock":    func() error { return execDevice("lock", "disengage") },
}

func execDevice(device, action string) error {
	cmd := exec.Command("./device_controller", device, action)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd.Run()
}

func main() {
	fmt.Print("Enter command: ")

	reader := bufio.NewReader(os.Stdin)
	input, err := reader.ReadString('\n')
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}

	command := strings.TrimSpace(strings.ToLower(input))

	// 验证命令是否在白名单中
	if execFunc, exists := allowedCommands[command]; exists {
		if err := execFunc(); err != nil {
			fmt.Fprintf(os.Stderr, "Execution failed: %v\n", err)
			os.Exit(1)
		}
	} else {
		fmt.Println("Unknown command. Available commands:")
		for cmd := range allowedCommands {
			fmt.Printf("  - %s\n", cmd)
		}
		os.Exit(1)
	}
}
```

