// main.go - 修复后的安全版本
package main

import (
	"context"
	"crypto/sha256"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"regexp"
	"time"
)

// 用户名验证正则：只允许字母、数字、下划线，3-20 字符
var usernameRegex = regexp.MustCompile(`^[a-zA-Z0-9_]{3,20}$`)

// UserData 用户数据结构
type UserData struct {
	Username string `json:"username"`
	Data     string `json:"data"`
}

// Config 安全配置
type Config struct {
	BaseURL    string
	AuthToken  string
	Timeout    time.Duration
}

func validateUsername(username string) error {
	if !usernameRegex.MatchString(username) {
		return errors.New("invalid username format")
	}
	return nil
}

func getUserData(ctx context.Context, username string, cfg Config) ([]byte, error) {
	// 1. 验证用户名
	if err := validateUsername(username); err != nil {
		return nil, fmt.Errorf("validation failed: %w", err)
	}

	// 2. 安全构建 URL
	baseURL, err := url.Parse(cfg.BaseURL)
	if err != nil {
		return nil, fmt.Errorf("invalid base URL: %w", err)
	}

	query := baseURL.Query()
	query.Set("user", username)
	baseURL.RawQuery = query.Encode()

	// 3. 创建带认证的请求
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, baseURL.String(), nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("Authorization", "Bearer "+cfg.AuthToken)
	req.Header.Set("Content-Type", "application/json")

	// 4. 发送请求
	client := &http.Client{Timeout: cfg.Timeout}
	resp, err := client.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()

	// 5. 检查响应状态
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("request failed with status: %d", resp.StatusCode)
	}

	// 6. 读取数据
	return io.ReadAll(resp.Body)
}

func main() {
	cfg := Config{
		BaseURL:   "https://example.com/getdata",
		AuthToken: "your-secure-token",
		Timeout:   10 * time.Second,
	}

	ctx, cancel := context.WithTimeout(context.Background(), cfg.Timeout)
	defer cancel()

	data, err := getUserData(ctx, "testuser", cfg)
	if err != nil {
		fmt.Println("Error:", err)
		return
	}

	hash := sha256.Sum256(data)
	fmt.Printf("Data hash: %x\n", hash)
}
