	"time"
)

type TestResult struct {
	TestName   string
	Vulnerable bool
	Details    string
}

var xssPayloads = []string{
	"<script>alert('XSS')</script>",
	"<img src=x onerror=alert('XSS')>",
	"javascript:alert('XSS')",
}

var sqlPayloads = []string{
	"' OR '1'='1",
	"1; DROP TABLE users--",
	"' UNION SELECT NULL--",
}

func makeRequest(method, targetURL string, params map[string]string) (*http.Response, error) {
	client := &http.Client{Timeout: 10 * time.Second}
	var req *http.Request
	var err error

	if method == "GET" {
		u, _ := url.Parse(targetURL)
		q := u.Query()
		for k, v := range params {
			q.Set(k, v)
		}
		u.RawQuery = q.Encode()
		req, err = http.NewRequest("GET", u.String(), nil)
	} else if method == "POST" {
		data := url.Values{}
		for k, v := range params {
			data.Set(k, v)
		}
		req, err = http.NewRequest("POST", targetURL, strings.NewReader(data.Encode()))
		req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	}
	if err != nil {
		return nil, err
	}
	req.Header.Set("User-Agent", "SecurityTestBot/1.0")
	return client.Do(req)
}

func testXSS(targetURL string) []TestResult {
	var results []TestResult
	for _, payload := range xssPayloads {
		resp, err := makeRequest("GET", targetURL, map[string]string{"q": payload})
		if err != nil {
			continue
		}
		body, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		if strings.Contains(string(body), payload) {
			results = append(results, TestResult{
				TestName:   "XSS Test",
				Vulnerable: true,
				Details:    fmt.Sprintf("Payload reflected: %s", payload),
			})
		}
	}
	return results
}

func testSQLi(targetURL string) []TestResult {
	var results []TestResult
	for _, payload := range sqlPayloads {
		resp, err := makeRequest("GET", targetURL, map[string]string{"id": payload})
		if err != nil {
			continue
		}
		body, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		if strings.Contains(strings.ToLower(string(body)), "sql") ||
			strings.Contains(string(body), "error") ||
			resp.StatusCode == 500 {
			results = append(results, TestResult{
				TestName:   "SQL Injection Test",
				Vulnerable: true,
				Details:    fmt.Sprintf("Possible SQLi with payload: %s", payload),
			})
		}
	}
	return results
}

func testSecurityHeaders(targetURL string) []TestResult {
	var results []TestResult
	resp, err := http.Get(targetURL)
	if err != nil {
		return results
	}
	defer resp.Body.Close()

	headers := map[string]string{
		"X-Content-Type-Options":  "nosniff",
		"X-Frame-Options":         "DENY",
		"X-XSS-Protection":        "1; mode=block",
		"Content-Security-Policy": "",
		"Strict-Transport-Security": "",
	}

	for header, expected := range headers {
		val := resp.Header.Get(header)
		if val == "" || (expected != "" && val != expected) {
			results = append(results, TestResult{
				TestName:   "Security Header Test",
				Vulnerable: true,
				Details:    fmt.Sprintf("Missing or incorrect header: %s", header),
			})
		}
	}
	return results
}

func testCSRF(targetURL string) []TestResult {
	var results []TestResult
	// 简化测试：检查是否存在 CSRF token 字段
	resp, err := http.Get(targetURL)
	if err != nil {
		return results
	}
	defer resp.Body.Close()
	body, _ := io.ReadAll(resp.Body)
	if !strings.Contains(string(body), "csrf") && !strings.Contains(string(body), "token") {
		results = append(results, TestResult{
			TestName:   "CSRF Token Test",
			Vulnerable: true,
			Details:    "No CSRF token detected in form",
		})
	}
	return results
}

func main() {
	target := "http://example.com/order" // 替换为实际测试目标

	fmt.Println("=== 安全测试开始 ===")
	allResults := append(testXSS(target), testSQLi(target)...)
	allResults = append(allResults, testSecurityHeaders(target)...)
	allResults = append(allResults, testCSRF(target)...)

	for _, r := range allResults {
		status := "✅ 安全"
		if r.Vulnerable {
			status = "⚠️ 存在风险"
		}
		fmt.Printf("[%s] %s - %s\n", status, r.TestName, r.Details)
	}
	fmt.Println("=== 安全测试结束 ===")
}
