### 3. API 客户端封装（client/api_client.go）

```go
package client

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"time"

	"real-estate-api/config"
	"real-estate-api/models"
)

type APIClient struct {
	httpClient *http.Client
	config     *config.Config
	logger     *log.Logger
}

func NewAPIClient(cfg *config.Config) *APIClient {
	return &APIClient{
		httpClient: &http.Client{
			Timeout: cfg.Timeout,
			Transport: &http.Transport{
				MaxIdleConns:        100,
				MaxIdleConnsPerHost: 10,
				IdleConnTimeout:     90 * time.Second,
			},
		},
		config: cfg,
		logger: log.New(io.Discard, "[API] ", log.LstdFlags),
	}
}

func (c *APIClient) SetLogger(logger *log.Logger) {
	c.logger = logger
}

func (c *APIClient) doRequest(ctx context.Context, method, path string, body interface{}, result interface{}) error {
	var reqBody io.Reader
	if body != nil {
		data, err := json.Marshal(body)
		if err != nil {
			return fmt.Errorf("marshal request body: %w", err)
		}
		reqBody = bytes.NewReader(data)
	}

	var lastErr error
	for attempt := 0; attempt <= c.config.MaxRetries; attempt++ {
		if attempt > 0 {
			c.logger.Printf("Retry attempt %d for %s %s", attempt, method, path)
			time.Sleep(c.config.RetryDelay * time.Duration(attempt))
		}

		req, err := http.NewRequestWithContext(ctx, method, c.config.BaseURL+path, reqBody)
		if err != nil {
			return fmt.Errorf("create request: %w", err)
		}

		req.Header.Set("Content-Type", "application/json")
		req.Header.Set("Authorization", "Bearer "+c.config.APIKey)
		req.Header.Set("User-Agent", "RealEstate-Client/1.0")

		resp, err := c.httpClient.Do(req)
		if err != nil {
			lastErr = err
			c.logger.Printf("Request failed: %v", err)
			continue
		}
		defer resp.Body.Close()

		respBody, err := io.ReadAll(resp.Body)
		if err != nil {
			lastErr = fmt.Errorf("read response: %w", err)
			continue
		}

		if resp.StatusCode >= 400 {
			var apiErr models.APIError
			if err := json.Unmarshal(respBody, &apiErr); err == nil {
				lastErr = apiErr
			} else {
				lastErr = fmt.Errorf("HTTP %d: %s", resp.StatusCode, string(respBody))
			}
			if resp.StatusCode >= 500 {
				continue // 可重试
			}
			return lastErr
		}

		if result != nil {
			if err := json.Unmarshal(respBody, result); err != nil {
				return fmt.Errorf("unmarshal response: %w", err)
			}
		}

		c.logger.Printf("Success: %s %s -> %d", method, path, resp.StatusCode)
		return nil
	}

	return fmt.Errorf("max retries exceeded: %w", lastErr)
}

func (c *APIClient) GetProperties(ctx context.Context, page, pageSize int) (*models.PropertyListResponse, error) {
	path := fmt.Sprintf("/properties?page=%d&page_size=%d", page, pageSize)
	var resp models.PropertyListResponse
	if err := c.doRequest(ctx, http.MethodGet, path, nil, &resp); err != nil {
		return nil, err
	}
	return &resp, nil
}

func (c *APIClient) GetPropertyByID(ctx context.Context, id string) (*models.Property, error) {
	path := fmt.Sprintf("/properties/%s", id)
	var prop models.Property
	if err := c.doRequest(ctx, http.MethodGet, path, nil, &prop); err != nil {
		return nil, err
	}
	return &prop, nil
}

func (c *APIClient) SendMessage(ctx context.Context, msg *models.MessageRequest) (*models.MessageResponse, error) {
	var resp models.MessageResponse
	if err := c.doRequest(ctx, http.MethodPost, "/messages", msg, &resp); err != nil {
		return nil, err
	}
	return &resp, nil
}
