                errorDiv.style.display = 'block';
                return false;
            }
        });

        // 从URL参数获取错误信息（后端重定向时传递）
        const urlParams = new URLSearchParams(window.location.search);
        const error = urlParams.get('error');
        if (error) {
            const errorDiv = document.getElementById('errorMessage');
