            $message = '无效的请求，请刷新页面重试。';
            $messageType = 'error';
        } else {
            // 输入验证和清理
            $name = trim($_POST['name'] ?? '');
            $email = trim($_POST['email'] ?? '');

            $errors = [];

            // 验证姓名
            if (empty($name) || strlen($name) < 2 || strlen($name) > 50) {
                $errors[] = '姓名长度应在2-50个字符之间';
            }

            // 验证邮箱
            if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
                $errors[] = '请输入有效的邮箱地址';
            }

            // 防止XSS
            $name = htmlspecialchars($name, ENT_QUOTES, 'UTF-8');
            $email = htmlspecialchars($email, ENT_QUOTES, 'UTF-8');

            if (empty($errors)) {
                // 加密存储（使用环境变量中的密钥）
                $encryptionKey = getenv('ENCRYPTION_KEY') ?: 'change-this-in-production';
                $data = [
                    'name' => $name,
                    'email' => $email,
                    'timestamp' => date('Y-m-d H:i:s'),
                    'ip' => $_SERVER['REMOTE_ADDR']
                ];

                // 使用JSON编码
                $jsonData = json_encode($data);

                // 加密数据（生产环境应使用更安全的加密方式）
                $encryptedData = openssl_encrypt(
                    $jsonData,
                    'AES-256-CBC',
                    hash('sha256', $encryptionKey),
                    0,
                    substr(hash('sha256', $encryptionKey), 0, 16)
                );

                // 安全存储（设置适当权限）
                $logFile = 'user_data.log';
                file_put_contents($logFile, $encryptedData . PHP_EOL, FILE_APPEND | LOCK_EX);

                // 设置文件权限（仅所有者可读写）
                chmod($logFile, 0600);

                $message = '信息提交成功！我们不会存储敏感支付信息。';
                $messageType = 'success';

                // 防止表单重复提交
                header("Location: " . $_SERVER['PHP_SELF'] . "?submitted=1");
                exit;
            } else {
                $message = implode('<br>', $errors);
                $messageType = 'error';
            }
        }
    }

    // 显示提交成功消息
    if (isset($_GET['submitted']) && $_GET['submitted'] == 1) {
        $message = '信息提交成功！我们不会存储敏感支付信息。';
        $messageType = 'success';
    }
    ?>

    <?php if ($message): ?>
        <div class="<?php echo $messageType === 'success' ? 'success' : 'warning'; ?>">
            <?php echo $message; ?>
        </div>
    <?php endif; ?>

    <form method="POST" action="">
        <input type="hidden" name="csrf_token" value="<?php echo $_SESSION['csrf_token']; ?>">

        <div class="form-group">
            <label for="name">姓名：</label>
            <input type="text" id="name" name="name" 
                   value="<?php echo htmlspecialchars($_POST['name'] ?? '', ENT_QUOTES, 'UTF-8'); ?>"
                   required minlength="2" maxlength="50" pattern="[A-Za-z\u4e00-\u9fa5\s]+">
        </div>

        <div class="form-group">
            <label for="email">电子邮件：</label>
            <input type="email" id="email" name="email" 
                   value="<?php echo htmlspecialchars($_POST['email'] ?? '', ENT_QUOTES, 'UTF-8'); ?>"
                   required maxlength="100">
        </div>

        <div class="form-group">
            <label>隐私说明：</label>
            <p style="font-size: 14px; color: #666;">
                ✓ 我们<strong>不收集</strong>信用卡、密码等敏感信息<br>
