  <div class="form-container">
    <h2>提交反馈或请求</h2>
    <form id="feedbackForm" novalidate>
      <div class="form-group">
        <label for="name">姓名 *</label>
        <input type="text" id="name" name="name" required />
        <div class="error" id="nameError">请输入您的姓名</div>
      </div>

      <div class="form-group">
        <label for="email">邮箱 *</label>
        <input type="email" id="email" name="email" required />
        <div class="error" id="emailError">请输入有效的邮箱地址</div>
      </div>

      <div class="form-group">
        <label for="type">反馈类型 *</label>
        <select id="type" name="type" required>
          <option value="">请选择类型</option>
          <option value="bug">问题报告</option>
          <option value="feature">功能请求</option>
          <option value="improvement">改进建议</option>
          <option value="other">其他</option>
        </select>
        <div class="error" id="typeError">请选择反馈类型</div>
      </div>

      <div class="form-group">
        <label for="message">反馈内容 *</label>
        <textarea id="message" name="message" required></textarea>
        <div class="error" id="messageError">请输入反馈内容（至少10个字符）</div>
      </div>

      <button type="submit">提交反馈</button>
    </form>

    <div class="success-message" id="successMessage">
      感谢您的反馈！我们已收到您的信息。
    </div>
  </div>

  <script>
    const form = document.getElementById('feedbackForm');
    const successMessage = document.getElementById('successMessage');

    const fields = {
      name: {
        input: document.getElementById('name'),
        error: document.getElementById('nameError'),
        validate: (val) => val.trim().length > 0
      },
      email: {
        input: document.getElementById('email'),
        error: document.getElementById('emailError'),
        validate: (val) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val)
      },
      type: {
        input: document.getElementById('type'),
        error: document.getElementById('typeError'),
        validate: (val) => val.trim() !== ''
      },
      message: {
        input: document.getElementById('message'),
        error: document.getElementById('messageError'),
        validate: (val) => val.trim().length >= 10
      }
    };

    function showError(field, show) {
      field.error.style.display = show ? 'block' : 'none';
      field.input.classList.toggle('invalid', show);
    }

    function validateField(field) {
      const value = field.input.value;
      const valid = field.validate(value);
      showError(field, !valid);
      return valid;
    }

    Object.values(fields).forEach(field => {
      field.input.addEventListener('blur', () => validateField(field));
      field.input.addEventListener('input', () => {
        if (field.input.classList.contains('invalid')) {
          validateField(field);
        }
      });
    });

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      let valid = true;
      Object.values(fields).forEach(field => {
        if (!validateField(field)) valid = false;
      });

      if (valid) {
        // 模拟提交
        console.log('表单数据：', {
          name: fields.name.input.value,
          email: fields.email.input.value,
          type: fields.type.input.value,
          message: fields.message.input.value
        });

        form.style.display = 'none';
        successMessage.style.display = 'block';
      }
    });
  </script>
</body>
