</head>
<body>
    <h1>上传媒体文件</h1>

    <div class="upload-container">
        <input type="file" id="mediaInput" accept="image/*,video/*" multiple>
        <br><br>
        <button onclick="handleUpload()">上传并预览</button>
        <button onclick="clearPreview()">清除预览</button>
    </div>

    <div id="message"></div>
    <div id="previewContainer"></div>

    <script>
        // 安全配置
        const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB
        const ALLOWED_IMAGE_TYPES = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];
        const ALLOWED_VIDEO_TYPES = ['video/mp4', 'video/webm', 'video/ogg'];

        function showMessage(text, type) {
            const msgDiv = document.getElementById('message');
            msgDiv.textContent = text;
            msgDiv.className = type;
            setTimeout(() => {
                msgDiv.textContent = '';
                msgDiv.className = '';
            }, 5000);
        }

        function validateFile(file) {
            // 验证文件大小
            if (file.size > MAX_FILE_SIZE) {
                return { valid: false, error: `文件 "${file.name}" 超过最大限制 10MB` };
            }

            // 验证文件类型
            const fileType = file.type.toLowerCase();
            const isImage = ALLOWED_IMAGE_TYPES.includes(fileType);
            const isVideo = ALLOWED_VIDEO_TYPES.includes(fileType);

            if (!isImage && !isVideo) {
                return { 
                    valid: false, 
                    error: `文件 "${file.name}" 类型不允许。只支持图片和视频文件` 
                };
            }

            // 验证文件扩展名（双重验证）
            const extension = file.name.split('.').pop().toLowerCase();
            const validExtensions = ['jpg', 'jpeg', 'png', 'gif', 'webp', 'mp4', 'webm', 'ogg'];
            if (!validExtensions.includes(extension)) {
                return { 
                    valid: false, 
                    error: `文件 "${file.name}" 扩展名不允许` 
                };
            }

            return { valid: true };
        }

        function createPreviewElement(file, url) {
            const fileType = file.type.toLowerCase();
            let element;

            if (fileType.startsWith('image/')) {
                element = document.createElement('img');
                element.alt = '上传的图片预览';
            } else if (fileType.startsWith('video/')) {
                element = document.createElement('video');
                element.controls = true;
                element.setAttribute('playsinline', 'true');
            }

            element.src = url;
            element.style.maxWidth = '100%';
            element.style.height = 'auto';
            element.style.margin = '10px 0';
            element.style.border = '1px solid #ddd';

            return element;
        }

        function handleUpload() {
            const input = document.getElementById('mediaInput');
            const previewContainer = document.getElementById('previewContainer');
            const files = input.files;

            if (files.length === 0) {
                showMessage('请选择至少一个文件', 'error');
                return;
            }

            // 清除之前的预览
            previewContainer.innerHTML = '';

            let successCount = 0;
            let errorCount = 0;

            // 处理每个文件
            Array.from(files).forEach((file, index) => {
                // 验证文件
                const validation = validateFile(file);
                if (!validation.valid) {
                    showMessage(validation.error, 'error');
                    errorCount++;
                    return;
                }

                // 使用 FileReader 进行本地预览（不上传到服务器）
                const reader = new FileReader();

                reader.onload = function(e) {
                    try {
                        const previewElement = createPreviewElement(file, e.target.result);
                        previewElement.id = `preview-${index}`;
                        previewContainer.appendChild(previewElement);
                        successCount++;

                        if (successCount === files.length - errorCount) {
                            showMessage(`成功预览 ${successCount} 个文件`, 'success');
                        }
                    } catch (error) {
                        console.error('预览创建失败:', error);
                        errorCount++;
                    }
                };

                reader.onerror = function() {
                    showMessage(`读取文件 "${file.name}" 失败`, 'error');
                    errorCount++;
                };

                // 读取文件为 Data URL
                reader.readAsDataURL(file);
            });
        }

        function clearPreview() {
            document.getElementById('mediaInput').value = '';
            document.getElementById('previewContainer').innerHTML = '';
            document.getElementById('message').textContent = '';
        }

