            margin-top: 8px;
        }

        .loading {
            text-align: center;
            padding: 20px;
            color: #666;
        }

        .error {
            background: #ffe6e6;
            color: #d63031;
            padding: 15px;
            border-radius: 4px;
            margin-bottom: 10px;
        }
    </style>
</head>
<body>
    <div class="comments-section">
        <h3>💬 评论 (<span id="comment-count">0</span>)</h3>
        <div id="comments-container">
            <div class="loading">加载中...</div>
        </div>
    </div>

    <script>
        // 模拟评论数据（实际项目中应从API获取）
        const commentsData = [
            "Great post! Love this place.",
            "Amazing content, keep it up!",
            "This is exactly what I needed, thank you!"
        ];

        // 动态加载评论
        function loadComments() {
            const container = document.getElementById('comments-container');
            const countSpan = document.getElementById('comment-count');

            try {
                // 清空加载提示
                container.innerHTML = '';

                // 更新评论数量
                countSpan.textContent = commentsData.length;

                // 动态创建评论元素
                commentsData.forEach((comment, index) => {
                    const commentDiv = document.createElement('div');
                    commentDiv.className = 'comment';
                    commentDiv.style.animationDelay = `${index * 0.1}s`;

                    commentDiv.innerHTML = `
                        <div class="comment-text">${escapeHtml(comment)}</div>
                        <div class="comment-meta">用户 ${index + 1} • 刚刚</div>
                    `;

                    container.appendChild(commentDiv);
                });

            } catch (error) {
                container.innerHTML = `
                    <div class="error">
                        ⚠️ 评论加载失败，请稍后重试
                    </div>
                `;
                console.error('评论加载错误:', error);
            }
        }

        // XSS防护 - 转义HTML特殊字符
        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        // 页面加载完成后执行
        document.addEventListener('DOMContentLoaded', loadComments);
    </script>
</body>
</html>
