                return PAYMENT_WHITELIST.some(whitelist => 
                    urlObj.origin === whitelist || urlObj.origin.startsWith(whitelist)
                );
            } catch (e) {
                return false;
            }
        }

        // 显示错误信息
        function showError(message) {
            const errorEl = document.getElementById('errorMessage');
            errorEl.textContent = message;
            errorEl.style.display = 'block';
        }

        // 隐藏错误信息
        function hideError() {
            const errorEl = document.getElementById('errorMessage');
            errorEl.style.display = 'none';
        }

        // 更新支付状态
        function updatePaymentStatus(status) {
            const statusEl = document.getElementById('paymentStatus');
            statusEl.textContent = status;
            statusEl.className = status === '加载完成' ? '' : 'loading';
        }

        // 动态更新支付页面的iframe
        function updatePaymentIframe(newSrc) {
            hideError();

            // 参数验证
            if (!newSrc || typeof newSrc !== 'string') {
                showError('无效的支付URL');
                return false;
            }

            // 安全验证
            if (!isValidPaymentUrl(newSrc)) {
                showError('支付URL不在白名单中');
                return false;
            }

            // XSS防护
            const sanitizedSrc = newSrc.replace(/javascript:/gi, '');

            try {
                const iframe = document.getElementById('paymentIframe');
                updatePaymentStatus('加载中...');
                iframe.src = sanitizedSrc;

                // 监听加载事件
                iframe.onload = function() {
                    updatePaymentStatus('加载完成');
                };

                iframe.onerror = function() {
                    updatePaymentStatus('加载失败');
                    showError('支付页面加载失败');
                };

                return true;
            } catch (e) {
                showError('更新支付页面失败：' + e.message);
                return false;
            }
        }

        // 获取当前支付URL
        function getCurrentPaymentUrl() {
            return document.getElementById('paymentIframe').src;
        }

        // 重置支付页面
        function resetPaymentIframe() {
            return updatePaymentIframe('https://paymentgateway.com/sandbox');
        }

        // 导出函数供测试使用
        if (typeof module !== 'undefined' && module.exports) {
            module.exports = {
                updatePaymentIframe,
                isValidPaymentUrl,
                getCurrentPaymentUrl,
                resetPaymentIframe
            };
        }
    </script>
