      <button class="clear" onclick="clearSearch()">清空</button>
    </div>

    <div class="stats" id="statsInfo">共 0 条反馈，匹配 0 条</div>

    <ul class="feedback-list" id="feedbackList"></ul>
  </div>

  <script>
    // 示例反馈数据
    const feedbackData = [
      { id: 1, user: "用户A", date: "2024-01-10", content: "产品价格偏高，但质量不错。" },
      { id: 2, user: "用户B", date: "2024-01-11", content: "客服服务态度很好，响应速度快。" },
      { id: 3, user: "用户C", date: "2024-01-12", content: "物流速度太慢了，等了两周才到。" },
      { id: 4, user: "用户D", date: "2024-01-13", content: "整体体验不错，会推荐给朋友。" },
      { id: 5, user: "用户E", date: "2024-01-14", content: "价格实惠，性价比高，质量也满意。" }
    ];

    const feedbackListEl = document.getElementById("feedbackList");
    const statsInfoEl = document.getElementById("statsInfo");
    const keywordInputEl = document.getElementById("keywordInput");

    // 初始化展示所有反馈
    renderFeedback(feedbackData);

    // 渲染反馈列表
    function renderFeedback(data, keyword = "") {
      feedbackListEl.innerHTML = "";
      if (data.length === 0) {
        feedbackListEl.innerHTML = `<li class="no-result">😕 未找到匹配内容</li>`;
        return;
      }

      data.forEach(item => {
        const li = document.createElement("li");
        li.className = "feedback-item";

        const highlighted = keyword ? highlightText(item.content, keyword) : escapeHtml(item.content);

        li.innerHTML = `
          <div class="feedback-meta">👤 ${escapeHtml(item.user)} | 📅 ${item.date}</div>
          <div class="feedback-content">${highlighted}</div>
        `;
        feedbackListEl.appendChild(li);
      });
    }

    // 搜索功能
    function searchFeedback() {
      const keyword = keywordInputEl.value.trim().toLowerCase();
      if (!keyword) {
        renderFeedback(feedbackData);
        updateStats(feedbackData.length, feedbackData.length);
        return;
      }

      const filtered = feedbackData.filter(item =>
        item.content.toLowerCase().includes(keyword)
      );

      renderFeedback(filtered, keyword);
      updateStats(feedbackData.length, filtered.length);
    }

    // 清空搜索
    function clearSearch() {
      keywordInputEl.value = "";
      renderFeedback(feedbackData);
      updateStats(feedbackData.length, feedbackData.length);
    }

    // 更新统计信息
    function updateStats(total, matched) {
      statsInfoEl.textContent = `共 ${total} 条反馈，匹配 ${matched} 条`;
    }

    // 高亮关键词
    function highlightText(text, keyword) {
      const escaped = escapeHtml(text);
      const regex = new RegExp(`(${escapeRegExp(keyword)})`, "gi");
      return escaped.replace(regex, '<span class="highlight">$1</span>');
