import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.jsontype.PolymorphicTypeValidator;
import com.fasterxml.jackson.databind.jsontype.BasicPolymorphicTypeValidator;

public class SecureJsonDeserializer {

    private static final ObjectMapper SAFE_MAPPER = createSafeMapper();

    private static ObjectMapper createSafeMapper() {
        ObjectMapper mapper = new ObjectMapper();

        // 1. 禁用默认类型识别
        mapper.disable(MapperFeature.DEFAULT_TYPING);

        // 2. 设置严格的类型验证器
        PolymorphicTypeValidator validator = BasicPolymorphicTypeValidator
            .builder()
            .allowIfSubType("com.example.model.")  // 只允许你的包
            .allowIfSubType("java.lang.String")
            .allowIfSubType("java.util.List")
            .build();

        mapper.setPolymorphicTypeValidator(validator);

        // 3. 禁用外部实体
        mapper.configure(
            com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, 
            true
        );

        return mapper;
    }

    public static <T> T deserialize(String json, Class<T> clazz) throws Exception {
        return SAFE_MAPPER.readValue(json, clazz);
    }
}
