import java.io.IOException;
import java.io.PrintWriter;
import javax.servlet.http.HttpServletResponse;
import org.apache.commons.text.StringEscapeUtils;

public class MessageDisplay {

    /**
     * 安全地将用户消息显示在页面上
     * @param message 用户输入的消息
     * @param response HTTP 响应对象
     */
    public void displayMessage(String message, HttpServletResponse response) {
        try {
            // 1. 设置响应内容类型和字符编码
            response.setContentType("text/html; charset=UTF-8");
            response.setCharacterEncoding("UTF-8");

            // 2. 对用户输入进行 HTML 转义，防止 XSS 攻击
            String safeMessage = StringEscapeUtils.escapeHtml4(message);

            // 3. 构建安全的 HTML 内容
            String html = "<html><head><meta charset='UTF-8'></head>" +
                          "<body><p>" + safeMessage + "</p></body></html>";

            // 4. 发送响应
            PrintWriter out = response.getWriter();
            out.print(html);
            out.flush();
        } catch (IOException e) {
            // 5. 错误处理
            e.printStackTrace();
        }
    }

    // 备选方案：如果不使用外部库，可使用自定义转义方法
    public void displayMessageWithCustomEscape(String message, HttpServletResponse response) {
        try {
            response.setContentType("text/html; charset=UTF-8");
            response.setCharacterEncoding("UTF-8");

            String safeMessage = escapeHtml(message);
            String html = "<html><head><meta charset='UTF-8'></head>" +
                          "<body><p>" + safeMessage + "</p></body></html>";

            PrintWriter out = response.getWriter();
            out.print(html);
            out.flush();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    // 自定义 HTML 转义方法
    private String escapeHtml(String input) {
        if (input == null) {
            return "";
        }
        return input.replace("&", "&amp;")
                    .replace("<", "&lt;")
                    .replace(">", "&gt;")
                    .replace("\"", "&quot;")
                    .replace("'", "&#x27;");
    }
}
```

### 关键修改点说明

| 修改项 | 说明 |
|--------|------|
| **HTML 转义** | 使用 `StringEscapeUtils.escapeHtml4()` 或自定义方法转义用户输入，防止 XSS 攻击 |
| **响应头设置** | 设置 `Content-Type` 和字符编码为 `UTF-8`，确保正确渲染 |
| **响应发送** | 使用 `PrintWriter` 输出 HTML 内容并刷新缓冲区 |
| **错误处理** | 捕获 `IOException` 并记录日志，避免程序崩溃 |
| **空值处理** | 自定义转义方法中对 `null` 输入进行处理，增强健壮性 |

