## 🔐 安全文件上传服务（FileUploadService.java）

```java
@Service
public class FileUploadService {

    @Value("${file.upload-dir}")
    private String uploadDir;

    @Value("${file.allowed-extensions}")
    private String allowedExtensions;

    @Value("${file.max-size-bytes}")
    private long maxSize;

    private static final Map<String, String> MIME_MAP = Map.of(
        "jpg", "image/jpeg", "jpeg", "image/jpeg", "png", "image/png",
        "gif", "image/gif", "pdf", "application/pdf",
        "doc", "application/msword", "docx", "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        "txt", "text/plain"
    );

    private static final Map<String, byte[]> MAGIC_NUMBERS = Map.of(
        "jpg", new byte[]{(byte)0xFF, (byte)0xD8, (byte)0xFF},
        "png", new byte[]{(byte)0x89, 0x50, 0x4E, 0x47},
        "gif", new byte[]{0x47, 0x49, 0x46},
        "pdf", new byte[]{0x25, 0x50, 0x44, 0x46}
    );

    public String uploadFile(MultipartFile file) throws IOException {
        validateFile(file);
        String originalFilename = file.getOriginalFilename();
        String ext = getFileExtension(originalFilename).toLowerCase();
        String safeFilename = generateSafeFilename(ext);
        Path filePath = Paths.get(uploadDir, safeFilename);
        Files.createDirectories(filePath.getParent());
        Files.write(filePath, file.getBytes());
        return safeFilename;
    }

    private void validateFile(MultipartFile file) throws IOException {
        if (file.isEmpty()) throw new IllegalArgumentException("文件不能为空");
        if (file.getSize() > maxSize) throw new IllegalArgumentException("文件过大");
        String ext = getFileExtension(file.getOriginalFilename()).toLowerCase();
        if (!allowedExtensions.contains(ext)) throw new IllegalArgumentException("不允许的文件类型");
        String mimeType = file.getContentType();
        if (!MIME_MAP.get(ext).equals(mimeType)) throw new IllegalArgumentException("MIME 类型不匹配");
        if (!validateMagicNumber(file.getInputStream(), ext)) throw new IllegalArgumentException("文件头校验失败");
    }

    private boolean validateMagicNumber(InputStream is, String ext) throws IOException {
        if (!MAGIC_NUMBERS.containsKey(ext)) return true;
        byte[] header = new byte[MAGIC_NUMBERS.get(ext).length];
        is.read(header);
        return Arrays.equals(header, MAGIC_NUMBERS.get(ext));
    }

    private String getFileExtension(String filename) {
        if (filename == null || !filename.contains(".")) return "";
        return filename.substring(filename.lastIndexOf(".") + 1);
    }

    private String generateSafeFilename(String ext) {
        return UUID.randomUUID().toString() + "." + ext;
    }
}
```

