class PaymentRecordValidator:
    """支付记录参数验证器"""

    @staticmethod
    def validate_user_id(user_id: Any) -> tuple[bool, str]:
        """验证用户ID"""
        if not user_id:
            return False, "用户ID不能为空"
        if not isinstance(user_id, str):
            return False, "用户ID必须是字符串类型"
        if len(user_id) < 3 or len(user_id) > 50:
            return False, "用户ID长度必须在3-50个字符之间"
        if not re.match(r'^[a-zA-Z0-9_-]+$', user_id):
            return False, "用户ID只能包含字母、数字、下划线和连字符"
        return True, ""

    @staticmethod
    def validate_card_number(card_number: Any) -> tuple[bool, str]:
        """验证卡号"""
        if not card_number:
            return True, ""  # 卡号为可选参数
        if not isinstance(card_number, str):
            return False, "卡号必须是字符串类型"
        # 移除空格和连字符
        cleaned_card = re.sub(r'[\s-]', '', card_number)
        if not cleaned_card.isdigit():
            return False, "卡号只能包含数字"
        if len(cleaned_card) < 13 or len(cleaned_card) > 19:
            return False, "卡号长度必须在13-19位之间"
        # Luhn算法验证
        if not PaymentRecordValidator._luhn_check(cleaned_card):
            return False, "卡号未通过Luhn算法验证"
        return True, cleaned_card

    @staticmethod
    def _luhn_check(card_number: str) -> bool:
        """Luhn算法验证卡号"""
        digits = [int(d) for d in card_number]
        odd_digits = digits[-1::-2]
        even_digits = digits[-2::-2]
        total = sum(odd_digits)
        for d in even_digits:
            total += sum(divmod(d * 2, 10))
        return total % 10 == 0

    @staticmethod
    def validate_date_range(start_date: Any, end_date: Any) -> tuple[bool, str]:
        """验证日期范围"""
        if not start_date and not end_date:
            return True, ""  # 日期为可选参数
        try:
            if start_date:
                if isinstance(start_date, str):
                    start_date = datetime.strptime(start_date, '%Y-%m-%d')
                elif not isinstance(start_date, datetime):
                    return False, "开始日期格式不正确"
            if end_date:
                if isinstance(end_date, str):
                    end_date = datetime.strptime(end_date, '%Y-%m-%d')
                elif not isinstance(end_date, datetime):
                    return False, "结束日期格式不正确"
            if start_date and end_date and start_date > end_date:
                return False, "开始日期不能晚于结束日期"
            return True, ""
