## 一、表结构定义（含约束与索引）

```sql
CREATE TABLE IF NOT EXISTS user_payment_sessions (
    session_id      VARCHAR(64) PRIMARY KEY,
    user_uid        BIGINT NOT NULL,
    session_info    JSONB NOT NULL,
    status          VARCHAR(20) DEFAULT 'active' CHECK (status IN ('active', 'completed', 'expired', 'cancelled')),
    created_at      TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at      TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    expires_at      TIMESTAMPTZ NOT NULL,
    ip_address      INET,
    user_agent      TEXT,
    amount          DECIMAL(10,2),
    currency        VARCHAR(3) DEFAULT 'CNY',

    CONSTRAINT chk_amount CHECK (amount IS NULL OR amount >= 0),
    CONSTRAINT chk_currency CHECK (currency ~ '^[A-Z]{3}$')
);

-- 索引优化
CREATE INDEX IF NOT EXISTS idx_user_uid ON user_payment_sessions(user_uid);
CREATE INDEX IF NOT EXISTS idx_status ON user_payment_sessions(status);
CREATE INDEX IF NOT EXISTS idx_expires_at ON user_payment_sessions(expires_at);
CREATE INDEX IF NOT EXISTS idx_created_at ON user_payment_sessions(created_at);
CREATE INDEX IF NOT EXISTS idx_session_info ON user_payment_sessions USING GIN(session_info);

-- 自动更新 updated_at 触发器
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_update_updated_at
    BEFORE UPDATE ON user_payment_sessions
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();
```

