CREATE OR REPLACE FUNCTION save_payment_session(
    p_session_id    VARCHAR(64),
    p_user_uid      BIGINT,
    p_session_info  JSONB,
    p_expires_at    TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP + INTERVAL '30 minutes',
    p_ip_address    INET DEFAULT NULL,
    p_user_agent    TEXT DEFAULT NULL,
    p_amount        DECIMAL(10,2) DEFAULT NULL,
    p_currency      VARCHAR(3) DEFAULT 'CNY'
)
RETURNS TABLE (
    success         BOOLEAN,
    message         TEXT,
    session_id      VARCHAR(64),
    operation       VARCHAR(20)
) AS $$
DECLARE
    v_existing_count INTEGER;
    v_session_info   JSONB;
BEGIN
    -- 参数验证
    IF p_session_id IS NULL OR p_session_id = '' THEN
        RETURN QUERY SELECT FALSE, 'Session ID cannot be empty', NULL::VARCHAR, NULL::VARCHAR;
        RETURN;
    END IF;

    IF p_user_uid IS NULL OR p_user_uid <= 0 THEN
        RETURN QUERY SELECT FALSE, 'Invalid user UID', NULL::VARCHAR, NULL::VARCHAR;
        RETURN;
    END IF;

    IF p_session_info IS NULL THEN
        RETURN QUERY SELECT FALSE, 'Session info cannot be null', NULL::VARCHAR, NULL::VARCHAR;
        RETURN;
    END IF;

    IF p_expires_at <= CURRENT_TIMESTAMP THEN
        RETURN QUERY SELECT FALSE, 'Expiration time must be in the future', NULL::VARCHAR, NULL::VARCHAR;
        RETURN;
    END IF;

    -- 清理 session_info 中敏感字段
    v_session_info = p_session_info - 'password' - 'cvv' - 'card_number';

    BEGIN
        SELECT COUNT(*) INTO v_existing_count
        FROM user_payment_sessions
        WHERE session_id = p_session_id;

        IF v_existing_count = 0 THEN
            INSERT INTO user_payment_sessions (
                session_id, user_uid, session_info, expires_at,
                ip_address, user_agent, amount, currency, status
            ) VALUES (
                p_session_id, p_user_uid, v_session_info, p_expires_at,
                p_ip_address, p_user_agent, p_amount, p_currency, 'active'
            );
            RETURN QUERY SELECT TRUE, 'Session created successfully', p_session_id, 'INSERT';
        ELSE
            UPDATE user_payment_sessions
            SET 
                user_uid = p_user_uid,
                session_info = v_session_info,
                expires_at = p_expires_at,
                ip_address = COALESCE(p_ip_address, ip_address),
                user_agent = COALESCE(p_user_agent, user_agent),
                amount = COALESCE(p_amount, amount),
                currency = COALESCE(p_currency, currency),
                status = 'active'
            WHERE session_id = p_session_id
              AND status != 'completed';

            IF FOUND THEN
                RETURN QUERY SELECT TRUE, 'Session updated successfully', p_session_id, 'UPDATE';
            ELSE
                RETURN QUERY SELECT FALSE, 'Session is completed and cannot be updated', p_session_id, 'UPDATE';
            END IF;
        END IF;

    EXCEPTION WHEN OTHERS THEN
        RETURN QUERY SELECT FALSE, 'Database error: ' || SQLERRM, p_session_id, 'ERROR';
    END;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
```

## 三、辅助函数（可选）

```sql
-- 获取有效会话
CREATE OR REPLACE FUNCTION get_active_session(p_user_uid BIGINT)
RETURNS TABLE (
    session_id  VARCHAR(64),
    session_info JSONB,
    expires_at  TIMESTAMPTZ,
    amount      DECIMAL(10,2)
) AS $$
BEGIN
    RETURN QUERY
    SELECT session_id, session_info, expires_at, amount
    FROM user_payment_sessions
    WHERE user_uid = p_user_uid
      AND status = 'active'
      AND expires_at > CURRENT_TIMESTAMP
    ORDER BY created_at DESC
    LIMIT 1;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 清理过期会话
CREATE OR REPLACE FUNCTION cleanup_expired_sessions()
RETURNS INTEGER AS $$
DECLARE
    v_count INTEGER;
BEGIN
    WITH deleted AS (
        DELETE FROM user_payment_sessions
        WHERE expires_at < CURRENT_TIMESTAMP
          AND status = 'active'
        RETURNING session_id
    )
    SELECT COUNT(*) INTO v_count FROM deleted;

    RETURN v_count;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
```

## 四、使用示例

```sql
-- 创建新会话
SELECT * FROM save_payment_session(
    'sess_abc123xyz',
    10001,
    '{"payment_method": "credit_card", "items": [{"id": 1, "qty": 2}]}',
    CURRENT_TIMESTAMP + INTERVAL '30 minutes',
    '192.168.1.100'::INET,
    'Mozilla/5.0',
    299.00,
    'CNY'
);

-- 查询活跃会话
SELECT * FROM get_active_session(10001);

-- 清理过期会话
SELECT cleanup_expired_sessions();
```

## 五、关键优化点说明

1. **数据完整性**：使用 CHECK 约束确保金额、货币、状态合法。
2. **安全性**：函数使用 SECURITY DEFINER，自动过滤敏感字段。
3. **性能优化**：为常用查询字段建立索引，session_info 使用 GIN 索引支持 JSON 查询。
4. **可维护性**：触发器自动维护 updated_at，函数封装业务逻辑。
5. **可扩展性**：支持会话更新、状态管理、过期清理等扩展功能。

该方案适用于高并发支付场景，具备良好的安全性、可维护性和扩展性。

